    #[test]
    fn duplicate_method_via_impl_and_extend_is_rejected() {
        // Regression for N8 (2026-05-22): `impl X:` and `extend X:` both
        // defining `get` silently produced two `def get` in the merged
        // class body — Python took the last one and one definition was
        // lost. The shape-merge pass dedup'd on `or_insert`, hiding it.
        let src = "\
class Box:
    value: int

impl Box:
    def get(self) -> int:
        return self.value

extend Box:
    def get(self) -> int:
        return self.value * 2
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::DuplicateMethod { method, .. } if method == "get")),
            "duplicate method must surface a diagnostic, got: {:?}",
            d.errors()
        );
    }

    #[test]
    fn duplicate_method_across_two_impl_blocks_is_rejected() {
        // Two `impl` blocks defining the same method also collide.
        let src = "\
class Box:
    value: int

impl Box:
    def get(self) -> int:
        return self.value

impl Box:
    def get(self) -> int:
        return 0
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::DuplicateMethod { .. })),
            "two impl blocks defining the same method must error: {:?}",
            d.errors()
        );
    }

    #[test]
    fn match_on_self_field_exhaustive_is_clean() {
        // Regression for N13 (2026-05-22): the exhaustiveness pass only
        // looked at bare-name subjects (`match s:`), so a class with a
        // sealed-union state field doing `match self.state:` falsely
        // tripped missing_return even when every variant was handled.
        let src = "\
type Status = Open | Closed
class Open:
    since: float
class Closed:
    label: str

class Foo:
    state: Status

impl Foo:
    def check(self) -> str:
        match self.state:
            case Open(_):
                return \"open\"
            case Closed(_):
                return \"closed\"
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::MissingReturn { .. })),
            "exhaustive match on `self.<field>` must not fire missing_return: {:?}",
            d.errors()
        );
    }

    #[test]
    fn match_on_impl_method_call_returning_result_is_clean() {
        // kilnlog #1: a `match` whose subject is a direct impl-method call
        // returning `Result[T, E]`, with `case Ok(_)`/`case Err(_)` arms that
        // all return/raise, falsely tripped missing_return. The readonly
        // inference typed a (non-property) bound-method value as Unknown, so
        // the call's return type never reached the exhaustiveness pass.
        // Free-function-call and bound-`let` subjects already worked.
        let src = "\
class Box:
    n: int

impl Box:
    def fetch(self) -> Result[int, str]:
        if self.n > 0:
            return Ok(self.n)
        return Err(\"empty\")

def broken(b: Box) -> int:
    match b.fetch():
        case Ok(v):
            return v
        case Err(e):
            raise ValueError(e)
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::MissingReturn { .. })),
            "exhaustive match on an impl-method call returning Result must not fire missing_return: {:?}",
            d.errors()
        );
    }

    #[test]
    fn checked_cast_types_as_target() {
        // `x as! int` types as `int`, and the boundary value (`object`) needs
        // no `unsafe:` block — the cast IS the boundary.
        let src = "def f(x: object) -> int:\n    let n: int = x as! int\n    return n\n";
        let d = check_full(src);
        assert!(
            d.errors().is_empty(),
            "an `as!` cast to the bound type must check cleanly: {:?}",
            d.errors()
        );
    }

    #[test]
    fn checked_cast_target_must_satisfy_annotation() {
        // The cast's static type is the target, so a mismatched binding
        // annotation still fires `type_mismatch` (the cast is not a blanket
        // `Any` escape hatch).
        let src = "def f(x: object) -> str:\n    let n: str = x as! int\n    return n\n";
        let d = check_full(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "casting to `int` then binding as `str` must mismatch: {:?}",
            d.errors()
        );
    }

    #[test]
    fn try_result_infers_result_type() {
        // `try_result(thunk, on_err)` types as `Result[T, E]` — T from the
        // thunk body, E from the mapper body — so returning it from a matching
        // `Result[int, str]`-typed function checks cleanly.
        let src = "def parse(raw: str) -> int:\n    return int(raw)\n\ndef safe(raw: str) -> Result[int, str]:\n    return try_result(lambda: parse(raw), lambda e: str(e))\n";
        let d = check_full(src);
        assert!(
            d.errors().is_empty(),
            "try_result returning the declared Result type must check cleanly: {:?}",
            d.errors()
        );
    }

    #[test]
    fn try_result_is_a_result_not_any() {
        // The combinator returns a `Result`, not a blanket `Any`: binding it to
        // a non-Result annotation still fires `type_mismatch`.
        let src = "def f() -> None:\n    let x: int = try_result(lambda: 1, lambda e: \"\")\n";
        let d = check_full(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "binding a `Result` to `int` must mismatch: {:?}",
            d.errors()
        );
    }

    #[test]
    fn fstring_is_str_not_unknown() {
        // An f-string evaluates to `str`, so binding one to `int` mismatches.
        // Regression: f-strings used to fall through to `Unknown`, silently
        // disabling type-checking of every f-string value.
        let src = "def f(n: int) -> None:\n    let x: int = f\"value {n}\"\n";
        let d = check_full(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "an f-string bound to `int` must mismatch: {:?}",
            d.errors()
        );
    }

    #[test]
    fn try_result_fstring_mapper_error_type_is_checked() {
        // The mapper's f-string error type (`str`) must flow through `?` and
        // fire `result_error_mismatch` against a function declaring a class
        // error type. Regression: the f-string mapper used to infer `Unknown`,
        // so `Result[T, Unknown]` slipped past the `?` error-type check.
        let src = "class AppErr:\n    msg: str\n\ndef f(raw: str) -> Result[int, AppErr]:\n    let n: int = try_result(lambda: int(raw), lambda e: f\"bad: {e}\")?\n    return Ok(n)\n";
        let d = check_full(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::ResultErrorMismatch { .. })),
            "f-string error mapper mismatching the declared error type must fire: {:?}",
            d.errors()
        );
    }

