    #[test]
    fn exhaustive_sealed_match_without_wildcard_satisfies_missing_return() {
        // Sealed-union exhaustiveness over Shape (Circle | Square) is
        // proven by listing every variant. Missing_return must respect
        // that and not fire even without a trailing `case _:`.
        let src = "\
class Circle:
    r: float
class Square:
    s: float

type Shape = Circle | Square

def area(s: Shape) -> float:
    match s:
        case Circle():
            return 1.0
        case Square():
            return 2.0
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::MissingReturn { .. })),
            "exhaustive sealed-union match should satisfy missing_return: {:?}",
            d.errors()
        );
    }

    #[test]
    fn unsafe_block_with_inner_returns_satisfies_missing_return() {
        // F2: `unsafe:` lowers to `if True:`, which is unconditional
        // flow — when every path inside the block returns/raises, the
        // function returns. Missing_return must not fire.
        let src = "\
def f(x: object) -> int:
    unsafe:
        if isinstance(x, int):
            return x
        raise ValueError(\"bad\")
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::MissingReturn { .. })),
            "unsafe block with terminal raise must satisfy missing_return: {:?}",
            d.errors()
        );
    }

    #[test]
    fn with_block_returning_body_satisfies_missing_return() {
        // F3: a `with` block whose body's last statement is a return
        // is a definite return of the enclosing function.
        let src = "\
def f() -> int:
    with open(\"x\") as g:
        return 1
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::MissingReturn { .. })),
            "with block ending in return must satisfy missing_return: {:?}",
            d.errors()
        );
    }

    #[test]
    fn with_block_raising_body_still_fires_missing_return() {
        // Codex PR #73 review: a `with` body that ends in `raise`
        // is NOT a definite function exit because the context
        // manager's `__exit__` can suppress the exception
        // (`contextlib.suppress(Exception)`, custom managers
        // returning truthy). Missing-return must still fire.
        let src = "\
from contextlib import suppress

def f() -> int:
    with suppress(Exception):
        raise ValueError(\"x\")
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::MissingReturn { .. })),
            "with+raise must still fire missing_return: {:?}",
            d.errors()
        );
    }

    #[test]
    fn await_on_callable_returning_awaitable_unwraps_payload() {
        // R3-1: `f: Callable[..., Awaitable[T]]` is the natural
        // surface for async middleware handlers — `await f(x)` must
        // type as `T`, not as `Awaitable[T]`.
        let src = "\
from typing import Callable, Awaitable

async def use(f: Callable[[int], Awaitable[str]]) -> str:
    let r: str = await f(1)
    return r
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "await on Callable[..., Awaitable[T]] must unwrap to T: {:?}",
            d.errors()
        );
    }

    #[test]
    fn await_on_callable_returning_coroutine_unwraps_payload() {
        // R3-1: same shape with `Coroutine[Y, S, T]` — the third
        // parameter is the awaited payload, per `typing.Coroutine`.
        let src = "\
from typing import Callable, Coroutine

async def use(f: Callable[[int], Coroutine[object, object, int]]) -> int:
    let n: int = await f(2)
    return n
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "await on Callable[..., Coroutine[X, Y, T]] must unwrap to T: {:?}",
            d.errors()
        );
    }

    #[test]
    fn ternary_isinstance_narrowing_fires_like_if_else() {
        // R3-9: ternary `body if test else orelse` previously
        // skipped narrowing entirely (the expression form fell
        // through to Type::Unknown). The fix makes ternary narrow
        // the same way `if/else` does — both directions.
        let src = "\
def consume_int(n: int) -> None:
    pass

def use(x: int | str) -> None:
    let _ = consume_int(x) if isinstance(x, int) else None
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "ternary isinstance narrowing must apply to truthy branch: {:?}",
            d.errors()
        );
    }

    #[test]
    fn ternary_nullable_narrowing_fires_like_if_else() {
        // R3-9: ternary `x if x is not None else default` narrows
        // `x` to the non-None branch on the truthy side.
        let src = "\
def consume_int(n: int) -> None:
    pass

def use(x: int | None) -> int:
    return x if x is not None else 0
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::NullableUse { .. })),
            "ternary `is not None` narrowing must strip None on truthy: {:?}",
            d.errors()
        );
    }

    #[test]
    fn narrowing_global_invalidated_by_call_in_assign_rhs() {
        // H6#3: a call in an assignment RHS may reassign a module global via
        // `global NAME`, staling a prior narrowing on that global.
        let src = "\
mut g: int | None = 1

def clear() -> int:
    global g
    g = None
    return 0

def use_it() -> int:
    if g is None:
        return -1
    let n: int = clear()
    return g
";
        let d = check(src);
        assert!(
            d.errors().iter().any(|e| matches!(
                e,
                TycError::NullableUse { .. } | TycError::TypeMismatch { .. }
            )),
            "global narrowing must be invalidated after a call in the RHS: {:?}",
            d.errors()
        );
    }

    #[test]
    fn narrowing_attr_invalidated_by_method_call() {
        // H6#4: a bare method-call statement may mutate a field of its
        // receiver, staling a prior `if self.x is not None:` narrowing.
        let src = "\
class Box:
    x: int | None

impl Box:
    def reset(self) -> None:
        self.x = None
    def use_it(self) -> int:
        if self.x is None:
            return -1
        self.reset()
        return self.x
";
        let d = check(src);
        assert!(
            d.errors().iter().any(|e| matches!(
                e,
                TycError::NullableUse { .. } | TycError::TypeMismatch { .. }
            )),
            "attr narrowing must be invalidated after a method call on the receiver: {:?}",
            d.errors()
        );
    }

    #[test]
    fn narrowing_attr_invalidated_by_awaited_method_call() {
        // The awaited twin of the case above: `await self.reset()` parses as
        // `Await(Call(...))`, which the bare-`Call` match missed, so the stale
        // narrowing survived across a suspension point that can null the field.
        let src = "\
class Box:
    x: int | None

impl Box:
    async def reset(self) -> None:
        self.x = None
    async def use_it(self) -> int:
        if self.x is None:
            return -1
        await self.reset()
        return self.x
";
        let d = check(src);
        assert!(
            d.errors().iter().any(|e| matches!(
                e,
                TycError::NullableUse { .. } | TycError::TypeMismatch { .. }
            )),
            "attr narrowing must be invalidated after an awaited method call: {:?}",
            d.errors()
        );
    }

    #[test]
    fn global_narrowing_does_not_leak_into_a_sibling_function() {
        // A narrowing established on a module global inside one function must
        // not persist into the next — `narrow()` mutates the module-scope
        // binding in place, and `check_function`'s `leave()` only pops the
        // body's own scope.
        let src = "\
mut CACHE: str | None = None

def use_it() -> int:
    if CACHE is None:
        return 0
    return len(CACHE)

def other() -> int:
    return len(CACHE)
";
        let d = check(src);
        assert!(
            !d.errors().is_empty(),
            "the leaked narrowing must not silence `len(CACHE)` in `other`: {:?}",
            d.errors()
        );
    }

    #[test]
    fn nonlocal_rebind_in_nested_def_does_not_leak_out() {
        // The false-positive direction: a nested `def` that nulls an outer
        // local via `nonlocal` must not leave the outer binding narrowed to
        // `None` for the enclosing body — the def is never called here.
        let src = "\
def outer(v0: int | None) -> int:
    mut v: int | None = v0
    if v is None:
        return 0
    def clear() -> None:
        nonlocal v
        v = None
    return v + 1
";
        let d = check(src);
        assert!(
            d.errors().is_empty(),
            "a narrowing must not leak out of a nested def (v is still int here): {:?}",
            d.errors()
        );
    }

    #[test]
    fn finally_sees_only_facts_guaranteed_on_every_path() {
        // A narrowing established partway through the body does not hold on the
        // raise path, which still runs `finally`.
        let src = "\
def f(x: str | None) -> int:
    try:
        if x is None:
            raise ValueError(\"nope\")
        return len(x)
    finally:
        print(x.upper())
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::NullableUse { .. })),
            "finally must see x as nullable (the raise path reaches it): {:?}",
            d.errors()
        );
    }

    #[test]
    fn finally_keeps_a_pre_try_narrowing() {
        // Control: a narrowing established BEFORE the try (here by an early
        // `if x is None: return`) holds in finally — it is a pre-try fact, so
        // the intersection with the pre-try state keeps it. No false positive.
        let src = "\
def g(x: str | None) -> int:
    if x is None:
        return 0
    try:
        return len(x)
    finally:
        print(x.upper())
";
        let d = check(src);
        assert!(
            d.errors().is_empty(),
            "a pre-try narrowing must survive into finally: {:?}",
            d.errors()
        );
    }

    #[test]
    fn finally_assignment_invalidates_downstream_narrowing() {
        // A `finally` runs on the normal-exit path, so an assignment it makes
        // flows to the code after the `try`. Here `x` is narrowed to `str`
        // before the `try`, but `finally: x = None` re-nullifies it — the
        // deref after the statement must be rejected (it crashes at runtime).
        let src = "\
def f(v: str | None) -> int:
    mut x: str | None = v
    if x is None:
        return 0
    try:
        pass
    finally:
        x = None
    return len(x.upper())
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::NullableUse { .. })),
            "a finally reassignment to None must invalidate the downstream \
             narrowing: {:?}",
            d.errors()
        );
    }

    #[test]
    fn finally_assignment_makes_value_safe_downstream() {
        // The dual: a `finally` assignment that re-establishes a non-null value
        // must be remembered downstream, so the deref is accepted — restoring
        // the pre-finally state would drop it and fire a false positive.
        let src = "\
def prod() -> str:
    return \"d\"

def f(v: str | None) -> int:
    mut x: str | None = v
    try:
        pass
    finally:
        x = prod()
    return len(x.upper())
";
        let d = check(src);
        assert!(
            d.errors().is_empty(),
            "a finally reassignment to a non-null value must be remembered \
             downstream (no false positive): {:?}",
            d.errors()
        );
    }

    #[test]
    fn finally_touching_one_var_keeps_another_narrowing() {
        // Overlaying finally's effect must not clobber a normal-path narrowing
        // the finally body never touched: `x` stays `str` even though the
        // finally block reassigns an unrelated `y`.
        let src = "\
def f(x: str | None, w: str | None) -> int:
    mut y: str | None = w
    if x is None:
        return 0
    try:
        pass
    finally:
        y = None
    return len(x.upper())
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::NullableUse { .. })),
            "a narrowing finally never touched must survive downstream: {:?}",
            d.errors()
        );
    }

    #[test]
    fn call_in_match_subject_invalidates_global_narrowing() {
        let src = "\
mut CACHE: str | None = \"hit\"

def clear() -> str:
    global CACHE
    CACHE = None
    return \"k\"

def use_it() -> int:
    if CACHE is None:
        return 0
    match clear():
        case _:
            pass
    return len(CACHE)
";
        let d = check(src);
        assert!(
            !d.errors().is_empty(),
            "a call in the match subject must invalidate the CACHE narrowing: {:?}",
            d.errors()
        );
    }

