    #[test]
    fn narrowing_loop_while_test_still_narrows_body() {
        // H6#2 control: the classic `while cur is not None:` linked-list walk
        // must stay clean — the test narrowing re-applies each pass on top of
        // the iteration-2 widening.
        let src = "\
class Node:
    value: int
    next: Node | None

def total(head: Node | None) -> int:
    mut cur: Node | None = head
    mut acc: int = 0
    while cur is not None:
        acc += cur.value
        cur = cur.next
    return acc
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::NullableUse { .. })),
            "while-test narrowing must survive the iteration-2 widening: {:?}",
            d.errors()
        );
    }

    #[test]
    fn async_with_as_binding_typed_from_aenter() {
        // R3-3: `as r` binds `__aenter__`'s return type so a
        // downstream `match r:` inside the body proves
        // exhaustiveness and `missing_return` doesn't spuriously
        // fire on the enclosing function. The fix lives in
        // `Stmt::With` check via `with_item_bound_type`.
        let src = "\
type Result = Ok | Err

class Ok:
    value: int

class Err:
    msg: str

class AsyncCtx:
    pass

impl AsyncCtx:
    async def __aenter__(self) -> Result:
        return Ok(value=1)
    async def __aexit__(self, *a: object) -> None:
        return None

async def with_match() -> int:
    async with AsyncCtx() as r:
        match r:
            case Ok(value):
                return value
            case Err(msg):
                return -1
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::MissingReturn { .. })),
            "async with exhaustive match tail must satisfy missing_return: {:?}",
            d.errors()
        );
    }

    #[test]
    fn generic_method_dispatch_substitutes_class_typevars() {
        // R3-15: `s: Stream[int].map(to_str)` needs `T` substituted
        // with `int` in the recorded method signature before the
        // call-site inference engine binds the method's own `U` from
        // the actual `to_str` callable type. Without the substitution
        // path the method's return type stayed `Stream[U]` /
        // effectively `Stream[object]`, accepting wrong annotations.
        let src = "\
from typing import Callable

class Stream[T]:
    items: list[T]

impl[T] Stream[T]:
    def map[U](self, f: Callable[[T], U]) -> Stream[U]:
        return Stream(items=[f(x) for x in self.items])
    def collect(self) -> list[T]:
        return self.items

def to_str(x: int) -> str:
    return str(x)

def consume_int_list(xs: list[int]) -> None:
    pass

def main() -> None:
    let s: Stream[int] = Stream(items=[1, 2, 3])
    let mapped = s.map(to_str)
    let result = mapped.collect()
    consume_int_list(result)
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "generic method dispatch must propagate U: list[str] should fail to assign to list[int]: {:?}",
            d.errors()
        );
    }

    #[test]
    fn generic_field_access_substitutes_class_typevars() {
        // R3-15 follow-on: field access on a generic instance must
        // also substitute the class's TypeVars. `let r: RecordEnv[int]`
        // calling `.payload` should resolve to `int`, not the bare
        // `T`.
        let src = "\
class RecordEnv[T]:
    payload: T

def consume_str(s: str) -> None:
    pass

def main() -> None:
    let r: RecordEnv[int] = RecordEnv(payload=42)
    consume_str(r.payload)
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "generic field access must propagate T: int field should fail to assign to str: {:?}",
            d.errors()
        );
    }

    #[test]
    fn generic_ctor_arg_rejected_str_into_int_from_annotation() {
        // SOUNDNESS HOLE regression: `let b: Box[int] = Box("hello")`
        // pins T=int from the annotation, so the `value` field is int.
        // Passing `"hello"` (str) must fire `tyc::type_mismatch` instead
        // of leaking through and crashing at `b.value + 1` at runtime.
        let src = "\
class Box[T]:
    value: T

def main() -> None:
    let b: Box[int] = Box(\"hello\")
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "str into Box[int] constructor must be rejected: {:?}",
            d.errors()
        );
    }

    #[test]
    fn generic_ctor_arg_rejected_explicit_typeargs() {
        // Explicit `Box[int]("hello")` form pins T=int via the
        // subscripted callee and must reject the str argument.
        let src = "\
class Box[T]:
    value: T

def main() -> None:
    let b = Box[int](\"hello\")
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "str into explicit Box[int](...) must be rejected: {:?}",
            d.errors()
        );
    }

    #[test]
    fn generic_ctor_arg_rejected_multiparam_pair() {
        // Multi-param generic: `Pair[int, str] = Pair("wrong", 99)` must
        // reject both args (str→int and int→str) against the pinned
        // type parameters.
        let src = "\
class Pair[A, B]:
    first: A
    second: B

def main() -> None:
    let p: Pair[int, str] = Pair(\"wrong\", 99)
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "wrong-typed Pair[int, str] construction must be rejected: {:?}",
            d.errors()
        );
    }

    #[test]
    fn generic_ctor_arg_correct_passes() {
        // No false positive: matching annotation and argument types.
        let src = "\
class Box[T]:
    value: T

def main() -> None:
    let b: Box[int] = Box(5)
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "correctly-typed Box[int] = Box(5) must pass: {:?}",
            d.errors()
        );
    }

    #[test]
    fn generic_ctor_arg_inferred_passes() {
        // No false positive: pure inference with no annotation must not
        // fire — `T` is unbound, so there is no concrete expectation to
        // violate.
        let src = "\
class Box[T]:
    value: T

def main() -> None:
    let b = Box(5)
    let _x: int = b.value
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "inferred Box(5) must pass: {:?}",
            d.errors()
        );
    }

    #[test]
    fn generic_ctor_arg_int_into_float_field_passes() {
        // No false positive: Typhon widens int → float, so `Box(3)` into
        // a `Box[float]` field is fine even though 3 is an int literal.
        let src = "\
class Box[T]:
    value: T

def main() -> None:
    let f: Box[float] = Box(3)
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "int into Box[float] must pass (int→float widening): {:?}",
            d.errors()
        );
    }

    #[test]
    fn generic_ctor_arg_none_into_optional_field_passes() {
        // No false positive: a `T?` field accepts None even when T=int.
        let src = "\
class Box[T]:
    value: T?

def main() -> None:
    let b: Box[int] = Box(None)
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "None into Box[int] with T? field must pass: {:?}",
            d.errors()
        );
    }

    #[test]
    fn class_field_default_ordering_rejected() {
        // R3-11: non-default field after defaulted field would
        // blow up the synthesised `__init__` at import time. The
        // checker now flags the ordering violation at compile time.
        let src = "\
class A:
    x: int
    y: int = 0
    z: int
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::FieldDefaultOrdering { .. })),
            "mixed-default class field ordering must fire field_default_ordering: {:?}",
            d.errors()
        );
    }

    #[test]
    fn class_fields_in_correct_order_is_clean() {
        let src = "\
class A:
    x: int
    y: int
    z: int = 0
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::FieldDefaultOrdering { .. })),
            "non-default-before-default order must not fire: {:?}",
            d.errors()
        );
    }

    #[test]
    fn inherited_default_then_subclass_required_field_rejected() {
        // A defaulted field on the base followed by a non-defaulted field on
        // the subclass produces `name, active=True, extra` in the merged
        // @dataclass — a non-default after a default, which raises TypeError at
        // import. Must be caught at check time (was missed: Sub's body only
        // declares `extra`).
        let src = "\
class Base:
    name: str
    active: bool = True

class Sub(Base):
    extra: int
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::FieldDefaultOrdering { .. })),
            "inherited-default + subclass-required must fire field_default_ordering: {:?}",
            d.errors()
        );
    }

    #[test]
    fn inherited_default_then_subclass_defaulted_is_clean() {
        // Valid: every field after the first default is itself defaulted.
        let src = "\
class Base:
    name: str
    active: bool = True

class Sub(Base):
    extra: int = 0
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::FieldDefaultOrdering { .. })),
            "subclass adding a defaulted field must not fire: {:?}",
            d.errors()
        );
    }

    #[test]
    fn exhaustive_result_match_satisfies_missing_return() {
        // F4: `match` over `Result[T, E]` covering both `Ok` and `Err`
        // arms (each ending in a return) is a definite return.
        let src = "\
def f(r: Result[int, str]) -> int:
    match r:
        case Ok(v):
            return v
        case Err(_):
            return -1
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::MissingReturn { .. })),
            "exhaustive Result match must satisfy missing_return: {:?}",
            d.errors()
        );
    }

    // ── FINDINGS #80: typo'd kwarg surfaces tyc::unknown_kwarg ────────

    #[test]
    fn typo_kwarg_emits_unknown_kwarg_with_suggestion() {
        let src = "\
def greet(name: str, greeting: str = \"Hello\") -> str:
    return greeting + \", \" + name

let r: str = greet(\"Amy\", greetinx=\"Hi\")
";
        let d = check(src);
        assert!(d.has_errors());
        let err = d
            .errors()
            .iter()
            .find(|e| matches!(e, TycError::UnknownKwarg { .. }))
            .expect("expected UnknownKwarg variant");
        let msg = format!("{}", err);
        assert!(
            msg.contains("greetinx") && msg.contains("greet"),
            "headline should name kwarg and function; got: {msg}"
        );
        // The suggestion should pick up the close match `greeting`.
        if let TycError::UnknownKwarg { suggestion, .. } = err {
            assert!(
                suggestion.contains("greeting"),
                "suggestion should propose `greeting`; got: {suggestion}"
            );
        }
    }

    #[test]
    fn unknown_kwarg_lists_candidates_when_no_close_match() {
        // Random kwarg that's nowhere near any parameter should fall
        // back to listing every accepted parameter name.
        let src = "\
def greet(name: str, greeting: str = \"Hello\") -> str:
    return greeting + \", \" + name

let r: str = greet(\"Amy\", xyzzy=\"Hi\")
";
        let d = check(src);
        let err = d
            .errors()
            .iter()
            .find(|e| matches!(e, TycError::UnknownKwarg { .. }))
            .expect("expected UnknownKwarg variant");
        if let TycError::UnknownKwarg { suggestion, .. } = err {
            assert!(
                suggestion.contains("name") && suggestion.contains("greeting"),
                "suggestion should list accepted params; got: {suggestion}"
            );
        }
    }

    #[test]
    fn function_with_double_star_kwarg_accepts_arbitrary_names() {
        // Functions declared with `**kwargs` should never emit
        // unknown_kwarg — anything is legal.
        let src = "\
def greet(name: str, **extras: str) -> str:
    return name

let r: str = greet(\"Amy\", weird_name=\"Hi\", another=\"x\")
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::UnknownKwarg { .. })),
            "**kwargs must absorb arbitrary names; got {:?}",
            d.errors()
        );
    }

