    #[test]
    fn newtype_accepts_explicit_construction() {
        let src = "\
newtype UserId = int
def greet(uid: UserId) -> str:
    return \"hi\"
let me: UserId = UserId(7)
let _msg: str = greet(me)
";
        let d = check(src);
        assert!(!d.has_errors(), "{:?}", d.errors());
    }

    #[test]
    fn newtype_rejects_bare_base_value() {
        let src = "\
newtype UserId = int
def greet(uid: UserId) -> str:
    return \"hi\"
let raw: int = 7
let _msg: str = greet(raw)
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "expected type mismatch on bare int → UserId"
        );
    }

    #[test]
    fn newtype_allows_escape_upward_to_base() {
        let src = "\
newtype UserId = int
def double(n: int) -> int:
    return n * 2
let me: UserId = UserId(7)
let _twice: int = double(me)
";
        let d = check(src);
        assert!(!d.has_errors(), "{:?}", d.errors());
    }

    #[test]
    fn newtype_rejects_cross_newtype_assignment() {
        let src = "\
newtype UserId = int
newtype PostId = int
def greet(uid: UserId) -> str:
    return \"hi\"
let post: PostId = PostId(42)
let _msg: str = greet(post)
";
        let d = check(src);
        assert!(d.has_errors(), "expected type mismatch on PostId → UserId");
    }

    #[test]
    fn newtype_constructor_arg_type_checked() {
        let src = "\
newtype UserId = int
let bad: UserId = UserId(\"seven\")
";
        let d = check(src);
        assert!(d.has_errors(), "expected newtype_violation for str arg");
    }

    #[test]
    fn concrete_constructor_arg_type_checked() {
        // A non-generic class with concrete scalar fields: a wrong-typed
        // keyword constructor argument (str where the field is int) must
        // fire `tyc::type_mismatch`.
        let bad = check(
            "class C:\n    host: str\n    port: int\n\nlet a: C = C(host=\"x\", port=\"nope\")\n",
        );
        assert!(bad.has_errors(), "expected type_mismatch on port=str");
        let msg = format!("{}", bad.errors()[0]);
        assert!(msg.contains("expected `int`"), "got {}", msg);
    }

    #[test]
    fn concrete_constructor_positional_arg_type_checked() {
        // Same, but the offending argument is positional.
        let bad =
            check("class C:\n    host: str\n    port: int\n\nlet a: C = C(\"x\", \"nope\")\n");
        assert!(
            bad.has_errors(),
            "expected type_mismatch on positional port=str"
        );
    }

    #[test]
    fn concrete_constructor_well_typed_args_pass() {
        // The well-typed constructor call must NOT regress to a false
        // positive. `8080` is an int (matches `port: int`), and an int
        // literal is fine for the `str` host only if it isn't — so use a
        // string for host. bool->int / int->float widening still apply.
        let good = check(
            "class C:\n    host: str\n    port: int\n\nlet a: C = C(host=\"x\", port=8080)\n",
        );
        assert!(
            !good.has_errors(),
            "well-typed constructor must pass: {:?}",
            good.errors()
        );
    }

    #[test]
    fn zero_field_constructor_rejects_excess_positional() {
        // A normal class with no fields takes no constructor args — too-many
        // positional is now caught (previously the arity check was skipped
        // for empty field lists).
        let bad = check("class Empty:\n    pass\n\nlet a: Empty = Empty(1)\n");
        assert!(bad.has_errors(), "Empty(1) should be rejected (0 fields)");
        let good = check("class Empty:\n    pass\n\nlet a: Empty = Empty()\n");
        assert!(!good.has_errors(), "Empty() must pass: {:?}", good.errors());
    }

    // NOTE: the `plain class` / `class!` exemption (an empty-field plain/raw
    // class must NOT be arity-checked, since it may carry a hand-written
    // `__init__`) is gated on `is_plain_class` / `is_raw_class`, which read
    // `resolved.plain_classes` / `raw_classes`. The in-crate `check()` harness
    // doesn't scrape those the way the CLI does, so it can't exercise that
    // path; it's verified end-to-end against the real binary and guaranteed
    // by the zero-false-positive sweep over the 256-file example corpus.

    #[test]
    fn newtype_self_cycle_does_not_overflow() {
        // PR #95 reviewer feedback: `newtype A = A` (and longer
        // chains like `A → B → A`) must not stack-overflow the
        // checker. The unwrap helper bounds the chain length so the
        // checker just rejects the assignment with a regular
        // `tyc::type_mismatch` instead of running away.
        let src = "\
newtype A = A
let x: A = 1
";
        let d = check(src);
        // We don't care WHICH diagnostic fires, only that the checker
        // finishes — the bug under repair was a stack overflow, not a
        // misclassification.
        let _ = d.errors();
    }

    #[test]
    fn newtype_mutual_cycle_does_not_overflow() {
        // Same guarantee for a two-step cycle.
        let src = "\
newtype A = B
newtype B = A
let x: A = 1
";
        let d = check(src);
        let _ = d.errors();
    }

    // ── blocking in async (Phase E) ─────────────────────────────────────

    #[test]
    fn blocking_call_in_async_def_warns() {
        let src = "\
import time
async def bad() -> None:
    time.sleep(1)
    return
";
        let d = check(src);
        assert!(
            d.warnings()
                .iter()
                .any(|w| matches!(w, TycError::BlockingInAsync { .. })),
            "expected blocking_in_async for time.sleep"
        );
    }

    #[test]
    fn requests_get_in_async_def_warns() {
        let src = "\
import requests
async def fetch() -> str:
    let r = requests.get(\"http://x\")
    return \"ok\"
";
        let d = check(src);
        assert!(
            d.warnings()
                .iter()
                .any(|w| matches!(w, TycError::BlockingInAsync { .. })),
            "expected blocking_in_async for requests.get"
        );
    }

    #[test]
    fn asyncio_to_thread_wrapper_does_not_warn() {
        // `asyncio.to_thread(time.sleep, 1)` itself is the wrapper;
        // the dotted-callee match only sees `asyncio.to_thread`,
        // which isn't in BLOCKING_CALLEES, so no warning fires.
        let src = "\
import asyncio
import time
async def good() -> None:
    await asyncio.to_thread(time.sleep, 1)
";
        let d = check(src);
        assert!(
            !d.warnings()
                .iter()
                .any(|w| matches!(w, TycError::BlockingInAsync { .. })),
            "asyncio.to_thread wrapper should not trip blocking_in_async"
        );
    }

    #[test]
    fn blocking_call_in_sync_def_does_not_warn() {
        // The blocking-in-async check only fires inside `async def`;
        // sync functions can call `time.sleep` freely.
        let src = "\
import time
def sync_caller() -> None:
    time.sleep(1)
";
        let d = check(src);
        assert!(
            !d.warnings()
                .iter()
                .any(|w| matches!(w, TycError::BlockingInAsync { .. })),
            "sync function should not trip blocking_in_async"
        );
    }

    #[test]
    fn unsafe_block_suppresses_blocking_warning() {
        let src = "\
import time
async def escape_hatch() -> None:
    unsafe:
        time.sleep(1)
    return
";
        let d = check(src);
        assert!(
            !d.warnings()
                .iter()
                .any(|w| matches!(w, TycError::BlockingInAsync { .. })),
            "unsafe: should suppress blocking_in_async"
        );
    }

