    #[test]
    fn pep695_function_type_params_resolve() {
        let src = "\
def first[T](items: list[T]) -> T:
    return items[0]
";
        let d = check(src);
        assert!(!d.has_errors(), "{:?}", d.errors());
    }

    #[test]
    fn pep695_generic_call_assignable_to_concrete_target() {
        // With T treated as Any in the signature, the return value satisfies
        // any annotation at the call site (until real inference lands).
        let src = "\
def first[T](items: list[T]) -> T:
    return items[0]

let xs: list[int] = [1, 2, 3]
let n: int = first(xs)
";
        let d = check(src);
        assert!(!d.has_errors(), "{:?}", d.errors());
    }

    #[test]
    fn bind_typevars_substitutes_simple_return() {
        // Direct unit test of the substitution helper: given `f[T](T) -> T`,
        // applying actual `int` to formal `T` should make the return `int`.
        let formals = vec![Type::TypeVar("T".to_owned())];
        let actuals = vec![Type::Int];
        let ret = Type::TypeVar("T".to_owned());
        let inferred = bind_typevars_and_substitute(&formals, &actuals, &ret);
        assert_eq!(inferred, Type::Int);
    }

    #[test]
    fn bind_typevars_substitutes_inside_generic() {
        // `f[T](list[T]) -> T` with actual `list[str]` should infer `T = str`.
        let formals = vec![Type::Generic(
            "list".to_owned(),
            vec![Type::TypeVar("T".to_owned())],
        )];
        let actuals = vec![Type::Generic("list".to_owned(), vec![Type::Str])];
        let ret = Type::TypeVar("T".to_owned());
        let inferred = bind_typevars_and_substitute(&formals, &actuals, &ret);
        assert_eq!(inferred, Type::Str);
    }

    #[test]
    fn bind_typevars_conflicting_args_widens_to_union() {
        // Calling `f[T](T, T)` with `(int, str)` should bind `T = int | str`.
        let formals = vec![Type::TypeVar("T".to_owned()), Type::TypeVar("T".to_owned())];
        let actuals = vec![Type::Int, Type::Str];
        let ret = Type::TypeVar("T".to_owned());
        let inferred = bind_typevars_and_substitute(&formals, &actuals, &ret);
        // Union variants are unordered semantically; check membership.
        match inferred {
            Type::Union(variants) => {
                assert!(variants.contains(&Type::Int));
                assert!(variants.contains(&Type::Str));
            }
            other => panic!("expected union, got {other:?}"),
        }
    }

    #[test]
    fn bidirectional_expected_pins_unbound_return_typevar() {
        // `make[T]() -> list[T]` has no args to infer T from, but the
        // call-site annotation `list[int]` should pin T.
        let formals: Vec<Type> = vec![];
        let actuals: Vec<Type> = vec![];
        let ret = Type::Generic("list".to_owned(), vec![Type::TypeVar("T".to_owned())]);
        let expected = Type::Generic("list".to_owned(), vec![Type::Int]);
        let inferred =
            bind_typevars_and_substitute_bidirectional(&formals, &actuals, &ret, Some(&expected));
        assert_eq!(inferred, Type::Generic("list".to_owned(), vec![Type::Int]));
    }

    #[test]
    fn bidirectional_forward_pass_wins_over_expected() {
        // When args already bind T, the expected type must not override the
        // forward result (the args carry more authoritative information).
        let formals = vec![Type::TypeVar("T".to_owned())];
        let actuals = vec![Type::Int];
        let ret = Type::TypeVar("T".to_owned());
        // Caller expects str but argument is int — arg wins, so the return
        // stays int and the assignment-check downstream catches the mismatch.
        let inferred =
            bind_typevars_and_substitute_bidirectional(&formals, &actuals, &ret, Some(&Type::Str));
        assert_eq!(inferred, Type::Int);
    }

    #[test]
    fn bidirectional_forward_binding_not_widened_by_expected() {
        // Regression for the backward-pass widening bug: with forward T=int
        // and expected return str, T must stay `int` (not be widened to
        // `int | str`).  At the assignment site the resulting `int` then
        // fails to match the `str` annotation, surfacing the real error.
        let src = "\
def id[T](x: T) -> T:
    return x

let s: str = id(3)
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "id(3) returns int; assigning to str must be rejected"
        );
        // The diagnostic must be a mismatch on `int`, not on `int | str`.
        let widened = d
            .errors()
            .iter()
            .any(|e| e.to_string().contains("int | str"));
        assert!(
            !widened,
            "expected type must not widen the forward-bound TypeVar; errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn variadic_tuple_accepts_fixed_length_literals() {
        // `tuple[T, ...]` is the homogeneous-variadic tuple type — same
        // element type at every position, length unconstrained. The
        // unifier must accept any fixed-length tuple literal whose
        // elements are all assignable to T (FINDINGS O3).
        let d = check("let xs: tuple[float, ...] = (1.0, 2.0, 3.0)\n");
        assert!(!d.has_errors(), "{:?}", d.errors());
        let d = check("let ys: tuple[float, ...] = ()\n");
        assert!(!d.has_errors(), "empty tuple should fit: {:?}", d.errors());
        let d = check("let zs: tuple[int, ...] = (1, 2, 3, 4, 5)\n");
        assert!(!d.has_errors(), "{:?}", d.errors());
    }

    #[test]
    fn variadic_tuple_widens_int_literals_to_float() {
        // The element-type hint flows into the tuple literal's slots
        // exactly like a fixed-arity expectation would, so int literals
        // widen to float when the target is `tuple[float, ...]`.
        let d = check("let xs: tuple[float, ...] = (1, 2, 3)\n");
        assert!(!d.has_errors(), "{:?}", d.errors());
    }

    // ── bool ⊆ int subtype widening ──────────────────────────────────────

    #[test]
    fn bool_assignable_to_int() {
        // CPython: bool is a strict subclass of int.
        let d = check("let x: int = True\n");
        assert!(
            !d.has_errors(),
            "bool must be assignable to int; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn bool_assignable_to_float() {
        // bool → int → float (transitive via widening chain).
        let d = check("let x: float = False\n");
        assert!(
            !d.has_errors(),
            "bool must be assignable to float; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn bool_arithmetic_with_int_yields_int() {
        // `1 + True` produces int (not Unknown).
        let d = check("let x: int = 1 + True\n");
        assert!(
            !d.has_errors(),
            "1 + True must type-check as int; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn bool_arithmetic_both_bools_yields_int() {
        // `True + False` has type int (Python: evaluates to 1).
        let d = check("let x: int = True + False\n");
        assert!(
            !d.has_errors(),
            "True + False must type-check as int; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn bool_unary_arithmetic_yields_int() {
        // `-True` produces int (`== -1`), `~True` produces int (`== -2`).
        let d = check("let x: int = -True\nlet y: int = ~True\n");
        assert!(
            !d.has_errors(),
            "unary -/~ on bool must yield int; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn int_not_assignable_to_bool() {
        // The widening is one-way: `let b: bool = 1` must still reject.
        let d = check("let b: bool = 1\n");
        assert!(
            d.has_errors(),
            "int must NOT flow into bool — the widening is one-way"
        );
    }

    #[test]
    fn binop_with_class_operand_stays_unknown_not_float() {
        // Regression: `4.0 * tensor_value + ...` must not over-promote
        // the result to `float` when one operand is a foreign class.
        // The previous `(Float, _) | (_, Float) => Float` arm rejected
        // valid numpy/torch code where the user annotated the result as
        // the foreign class (`let y: torch.Tensor = 4.0 * x.sum()`).
        let d = check(
            "class Tensor: dummy: int\n\
             def f(t: Tensor) -> Tensor:\n\
             \x20   return 4.0 * t\n",
        );
        // The call site `4.0 * t` should infer to Unknown (we don't
        // know Tensor.__rmul__), letting the surrounding `-> Tensor`
        // annotation drive assignability via the (Unknown, _) arm.
        assert!(
            !d.has_errors(),
            "binop with a foreign class operand must not over-promote to float; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn with_target_typed_from_enter() {
        // R3-3: `with x as r:` binds `r` to the type returned by
        // `__enter__`. Previously `r` was `Unknown`, so `r.no_attr`
        // and `r` flowing into a typed slot both slipped past the
        // checker (Unknown is assignable to anything).
        let d = check(
            "class Lock:\n\
             \x20   name: str\n\
             impl Lock:\n\
             \x20   def __enter__(self) -> Lock: return self\n\
             \x20   def __exit__(self, *args) -> None: pass\n\
             def takes_int(n: int) -> int: return n\n\
             def main() -> None:\n\
             \x20   let lk: Lock = Lock(name=\"x\")\n\
             \x20   with lk as r:\n\
             \x20       let bad: int = takes_int(r)\n",
        );
        // `r` is Lock; passing it to takes_int(n: int) must mismatch.
        assert!(
            d.has_errors(),
            "with-as target must be typed from __enter__ — got no errors"
        );
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "expected TypeMismatch for Lock-into-int; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn async_with_target_typed_from_aenter() {
        // R3-3: same as the sync case but `async with` consults
        // `__aenter__` instead of `__enter__`.
        let d = check(
            "class AsyncLock:\n\
             \x20   name: str\n\
             impl AsyncLock:\n\
             \x20   async def __aenter__(self) -> AsyncLock: return self\n\
             \x20   async def __aexit__(self, *args) -> None: pass\n\
             def takes_int(n: int) -> int: return n\n\
             async def use() -> int:\n\
             \x20   let lk: AsyncLock = AsyncLock(name=\"x\")\n\
             \x20   async with lk as r:\n\
             \x20       return takes_int(r)\n",
        );
        assert!(
            d.has_errors(),
            "async with target must be typed from __aenter__"
        );
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "expected TypeMismatch for AsyncLock-into-int; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn with_target_typed_from_contextmanager_yield() {
        // R3-3 frontier: `@contextmanager`-decorated generator factory
        // — `with cm() as r:` binds `r` to the yielded class type, not
        // the function's `Iterator[T]` return annotation.
        let d = check(
            "from contextlib import contextmanager\n\
             from typing import Iterator\n\
             class Conn:\n\
             \x20   id: int\n\
             @contextmanager\n\
             def acquire() -> Iterator[Conn]:\n\
             \x20   yield Conn(id=42)\n\
             def takes_str(s: str) -> str: return s\n\
             def main() -> None:\n\
             \x20   with acquire() as r:\n\
             \x20       let bad: str = takes_str(r)\n",
        );
        assert!(
            d.has_errors(),
            "@contextmanager yield Conn(...) must type r as Conn"
        );
    }

    #[test]
    fn async_with_target_typed_from_asynccontextmanager_yield() {
        // R3-3 frontier: same as above but for the async form. This is
        // the specific case TYPHON_FEEDBACK flagged as still leaving r
        // as Unknown.
        let d = check(
            "from contextlib import asynccontextmanager\n\
             from typing import AsyncIterator\n\
             class Session:\n\
             \x20   name: str\n\
             @asynccontextmanager\n\
             async def open_session() -> AsyncIterator[Session]:\n\
             \x20   yield Session(name=\"x\")\n\
             def takes_int(n: int) -> int: return n\n\
             async def use() -> int:\n\
             \x20   async with open_session() as r:\n\
             \x20       return takes_int(r)\n",
        );
        assert!(
            d.has_errors(),
            "@asynccontextmanager yield Session(...) must type r as Session"
        );
    }

    #[test]
    fn contextmanager_yield_local_with_annotation_resolves() {
        // R3-3 follow-up: `yield s` where `s = let s: Session = …`
        // resolves to `Session` via the pre-collected local-annotation
        // map, not just literal / constructor / None payloads. This
        // closes the carry-over case where the canonical "open, then
        // yield" shape (open into a local, yield the local) still
        // left `r` as Unknown.
        let d = check(
            "from contextlib import contextmanager\n\
             from typing import Iterator\n\
             class Conn:\n\
             \x20   id: int\n\
             @contextmanager\n\
             def acquire() -> Iterator[Conn]:\n\
             \x20   let c: Conn = Conn(id=42)\n\
             \x20   yield c\n\
             def takes_str(s: str) -> str: return s\n\
             def main() -> None:\n\
             \x20   with acquire() as r:\n\
             \x20       let bad: str = takes_str(r)\n",
        );
        assert!(
            d.has_errors(),
            "yield <local-with-annotation> must propagate the local's type to the as-target"
        );
    }

    #[test]
    fn with_target_unknown_when_unresolvable_falls_back_silently() {
        // Regression: when neither the factory pre-scan nor the
        // __enter__ lookup gives us a type, `r` stays Unknown so the
        // permissive `with open(path) as f:` path (stdlib stubs, no
        // declared __enter__) keeps working without spurious errors.
        let d = check(
            "def main() -> None:\n\
             \x20   with open(\"/tmp/x\") as f:\n\
             \x20       let s: str = f.read()\n",
        );
        // Should NOT explode; the assignment is permissive on Unknown.
        assert!(
            !d.has_errors(),
            "stdlib with-block must not regress; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn with_target_typed_from_attribute_contextmanager_call() {
        // R3-3 review: `pool.session()` (attribute-style callee) must
        // resolve the same way `session()` (bare name) does — both go
        // through `contextmanager_yields`, which is keyed by the
        // function/method name. Without `Expr::Attribute` support the
        // method-based factory shape (the canonical
        // `with self.acquire() as conn:` form) silently left `r` as
        // Unknown.
        let d = check(
            "from contextlib import contextmanager\n\
             from typing import Iterator\n\
             class Conn:\n\
             \x20   id: int\n\
             class Pool:\n\
             \x20   name: str\n\
             impl Pool:\n\
             \x20   @contextmanager\n\
             \x20   def acquire(self) -> Iterator[Conn]:\n\
             \x20       yield Conn(id=1)\n\
             def takes_str(s: str) -> str: return s\n\
             def main(p: Pool) -> None:\n\
             \x20   with p.acquire() as r:\n\
             \x20       let bad: str = takes_str(r)\n",
        );
        assert!(
            d.has_errors(),
            "attribute-form contextmanager call must propagate yield type to `r`"
        );
    }

    #[test]
    fn await_unwraps_awaitable_in_callable_return() {
        // R3-1: `Callable[..., Awaitable[T]]` is the canonical async-
        // middleware shape (FastAPI/Starlette/aiohttp). Calling the
        // callable returns `Awaitable[T]`; awaiting it must produce
        // `T`, not `Awaitable[T]`. Without the unwrap, the `let r: T =
        // await nxt(x)` line at the heart of every middleware chain
        // fires a spurious `type_mismatch: expected T, found
        // Awaitable[T]`.
        let d = check(
            "from typing import Callable, Awaitable\n\
             type NextFn = Callable[[int], Awaitable[int]]\n\
             async def caller(nxt: NextFn) -> int:\n\
             \x20   let r: int = await nxt(42)\n\
             \x20   return r\n",
        );
        assert!(
            !d.has_errors(),
            "await on Callable[..., Awaitable[T]] must produce T; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn await_unwraps_coroutine_third_param() {
        // R3-1: `Coroutine[Y, S, T]` carries the awaited result in its
        // third type parameter (typing-spec contract). mypy / pyright
        // unwrap the same way; Typhon must too.
        let d = check(
            "from typing import Callable, Coroutine\n\
             type ProcFn = Callable[[int], Coroutine[None, None, str]]\n\
             async def caller(p: ProcFn) -> str:\n\
             \x20   let r: str = await p(42)\n\
             \x20   return r\n",
        );
        assert!(
            !d.has_errors(),
            "await on Callable[..., Coroutine[Y,S,T]] must produce T; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn await_on_async_def_still_returns_declared_type() {
        // Regression: the unwrap added for R3-1 must not change the
        // canonical `async def f() -> int: ...; await f()` path. The
        // checker tracks `async def` as returning `int` directly (not
        // `Awaitable[int]`), so the unwrap arms shouldn't fire and the
        // result must stay `int`.
        let d = check(
            "async def fetch() -> int:\n\
             \x20   return 1\n\
             async def main() -> int:\n\
             \x20   let v: int = await fetch()\n\
             \x20   return v\n",
        );
        assert!(
            !d.has_errors(),
            "regression: await on async def f() -> int must still be int; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn da_pass_clean_when_every_branch_assigns() {
        // R3-8: `let x: int; if cond: x = a else: x = b; return x` is
        // legal — the DA pass intersects the post-branch assigned
        // sets and finds `x` in both, so the post-if read is fine.
        let d = check(
            "def f(cond: bool) -> int:\n\
             \x20   let x: int\n\
             \x20   if cond:\n\
             \x20       x = 5\n\
             \x20   else:\n\
             \x20       x = 10\n\
             \x20   return x\n",
        );
        assert!(
            !d.has_errors(),
            "every-branch-assigns must check clean; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn da_pass_flags_missing_else_branch() {
        // R3-8: dropping the `else` clause leaves an implicit
        // fall-through where `x` was never assigned — the
        // post-if read must fire `tyc::use_of_uninitialised`.
        let d = check(
            "def f(cond: bool) -> int:\n\
             \x20   let x: int\n\
             \x20   if cond:\n\
             \x20       x = 5\n\
             \x20   return x\n",
        );
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::UseOfUninitialised { .. })),
            "missing else branch must fire use_of_uninitialised; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn da_pass_clean_when_else_branch_diverges() {
        // R3-8: a diverging branch (`return`/`raise`) is excluded from
        // the intersection. `if cond: x = a else: return -1; use x`
        // is therefore fine.
        let d = check(
            "def f(cond: bool) -> int:\n\
             \x20   let x: int\n\
             \x20   if cond:\n\
             \x20       x = 5\n\
             \x20   else:\n\
             \x20       return -1\n\
             \x20   return x\n",
        );
        assert!(
            !d.has_errors(),
            "diverging else branch must satisfy DA; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn da_pass_clean_for_exhaustive_result_match() {
        // R3-8: the canonical declare-then-assign-in-arms shape over
        // Result — both `Ok` and `Err` arms covered, even when the
        // subject's call return type can't be inferred (the
        // structural-coverage path in `match_is_exhaustive_for_da`
        // recognises the Ok/Err pattern pair).
        let d = check(
            "def _load(success: bool) -> Result[int, str]:\n\
             \x20   if success:\n\
             \x20       return Ok(42)\n\
             \x20   return Err(\"nope\")\n\
             def use(s: bool) -> Result[int, str]:\n\
             \x20   let loaded: int\n\
             \x20   match _load(s):\n\
             \x20       case Ok(v):\n\
             \x20           loaded = v\n\
             \x20       case Err(e):\n\
             \x20           return Err(e)\n\
             \x20   return Ok(loaded)\n",
        );
        assert!(
            !d.has_errors(),
            "exhaustive Result match must satisfy DA; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn da_pass_clean_when_loop_does_not_initialise() {
        // R3-8: assignments inside a `for` body don't propagate out
        // because the loop body may execute zero times. Reading the
        // tracked binding AFTER the loop without a pre-loop assign
        // must fire.
        let d = check(
            "def f(xs: list[int]) -> int:\n\
             \x20   let total: int\n\
             \x20   for x in xs:\n\
             \x20       total = x\n\
             \x20   return total\n",
        );
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::UseOfUninitialised { .. })),
            "loop-body-only assignment must NOT count as init; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn da_pass_walrus_in_if_test_initialises_binding() {
        // R3-8 review (codex P2): the walrus operator `(x := expr)` in
        // an `if`-test must mark `x` as assigned in the surrounding
        // state so the body and post-if reads don't fire
        // `use_of_uninitialised`. Without `Expr::Named` handling the
        // walrus assignment was invisible to the DA pass.
        let d = check(
            "def f() -> int:\n\
             \x20   let x: int\n\
             \x20   if (x := 5) > 0:\n\
             \x20       return x\n\
             \x20   return x\n",
        );
        assert!(
            !d.has_errors(),
            "walrus in if-test must initialise the binding for the body and \
             post-if read; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn da_pass_walrus_rhs_checks_for_uses() {
        // R3-8 review: the walrus' RHS is a normal expression that
        // must itself be checked for uses of uninitialised bindings —
        // `(x := y + 1)` with `y` uninit must fire on `y`.
        let d = check(
            "def f() -> int:\n\
             \x20   let y: int\n\
             \x20   let z: int = (y + 1)\n\
             \x20   return z\n",
        );
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::UseOfUninitialised { name, .. } if name == "y")),
            "RHS of an expression must still be checked for uninit reads; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn newtype_arith_same_newtype_preserved() {
        // R2-12: `LogIndex + LogIndex` must stay `LogIndex` so the
        // result can flow into a `LogIndex`-typed slot without an
        // explicit `int(...)`/`LogIndex(...)` round-trip.
        let d = check(
            "newtype LogIndex = int\n\
             def main() -> None:\n\
             \x20   let a: LogIndex = LogIndex(1)\n\
             \x20   let b: LogIndex = LogIndex(2)\n\
             \x20   let sum: LogIndex = a + b\n\
             \x20   let diff: LogIndex = a - b\n\
             \x20   let prod: LogIndex = a * b\n",
        );
        assert!(
            !d.has_errors(),
            "same-newtype arithmetic must preserve the newtype; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn newtype_arith_literal_rhs_preserved() {
        // R2-12: `LogIndex + 1` must stay `LogIndex` — one-sided
        // arithmetic with a literal of the newtype's base type is
        // the canonical "advance by one" shape (commit index, log
        // index, watermark, byte offset).
        let d = check(
            "newtype LogIndex = int\n\
             def main() -> None:\n\
             \x20   let a: LogIndex = LogIndex(1)\n\
             \x20   let next: LogIndex = a + 1\n\
             \x20   let prev: LogIndex = a - 1\n\
             \x20   let scaled: LogIndex = 2 * a\n",
        );
        assert!(
            !d.has_errors(),
            "newtype + literal must preserve the newtype; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn newtype_arith_cross_newtype_rejected() {
        // R2-12: `LogIndex + Term` must fire `operator_type_mismatch`
        // — the whole point of the nominal alias is that LogIndex and
        // Term are not silently interchangeable just because they share
        // an int base.
        let d = check(
            "newtype LogIndex = int\n\
             newtype Term = int\n\
             def main() -> None:\n\
             \x20   let a: LogIndex = LogIndex(1)\n\
             \x20   let t: Term = Term(2)\n\
             \x20   let bad: LogIndex = a + t\n",
        );
        assert!(d.has_errors(), "cross-newtype arithmetic must be rejected",);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::OperatorTypeMismatch { .. })),
            "expected OperatorTypeMismatch; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn newtype_arith_division_widens_to_float() {
        // R2-12: Python's `/` is always true division, so even
        // `LogIndex / LogIndex` yields `float` — the newtype tag is
        // intentionally lost on `/` so the user sees the type widen at
        // the call site. Floor-division `//` keeps the newtype.
        let d = check(
            "newtype LogIndex = int\n\
             def main() -> None:\n\
             \x20   let a: LogIndex = LogIndex(10)\n\
             \x20   let b: LogIndex = LogIndex(3)\n\
             \x20   let quot: float = a / b\n\
             \x20   let floor: LogIndex = a // b\n",
        );
        assert!(
            !d.has_errors(),
            "division on newtype operands must widen to float; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn newtype_arith_float_newtype_with_int_literal() {
        // R2-12: float-based newtypes accept int/bool literals on the
        // same axis — `Money + 0` stays `Money` (Python's `1.0 + 1 → 1.0`).
        let d = check(
            "newtype Money = float\n\
             def main() -> None:\n\
             \x20   let a: Money = Money(1.5)\n\
             \x20   let plus_zero: Money = a + 0\n\
             \x20   let scaled: Money = a * 2\n",
        );
        assert!(
            !d.has_errors(),
            "float-newtype + int literal must preserve the newtype; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn newtype_arith_chain_preserves_newtype() {
        // R2-12: `newtype A = B; newtype B = int` must still resolve
        // through `unwrap_newtype_base` so chained newtypes behave the
        // same way as direct ones.
        let d = check(
            "newtype Inner = int\n\
             newtype Outer = Inner\n\
             def main() -> None:\n\
             \x20   let a: Outer = Outer(Inner(1))\n\
             \x20   let b: Outer = a + 1\n",
        );
        assert!(
            !d.has_errors(),
            "newtype chain arithmetic must preserve the outermost newtype; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn fixed_arity_tuple_widens_every_position() {
        // Every slot of a fixed-arity tuple is covariant, not just the
        // first — `tuple[int, int]` must flow into a `tuple[float, float]`
        // parameter exactly as it does into `tuple[float, ...]`. The
        // earlier `("tuple", 0) => Covariant` arm only relaxed position
        // 0, so a `tuple[int, int]` argument tripped invariance at
        // position 1 and rejected.
        let d = check(
            "def takes(p: tuple[float, float]) -> float: return p[0] + p[1]\n\
             def main() -> float: return takes((1, 2))\n",
        );
        assert!(
            !d.has_errors(),
            "tuple[int, int] must flow into tuple[float, float]; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn fixed_arity_tuple_rejects_unsound_widening() {
        // Covariance is one-way: `tuple[float, float]` does NOT flow into
        // `tuple[int, int]` (a float-typed value cannot be read as int).
        let d = check(
            "def takes(p: tuple[int, int]) -> int: return p[0] + p[1]\n\
             def main() -> int: return takes((1.0, 2.0))\n",
        );
        assert!(
            d.has_errors(),
            "tuple[float, float] must NOT flow into tuple[int, int]",
        );
    }

    #[test]
    fn variadic_tuple_rejects_mismatched_element() {
        // A wrong element type must still surface — the variadic
        // marker only relaxes arity, not the per-element type check.
        let d = check("let xs: tuple[float, ...] = (1.0, \"oops\", 3.0)\n");
        assert!(d.has_errors(), "expected str-vs-float to be rejected");
        // The diagnostic should render the expected type in its source
        // form (`tuple[T, ...]`), not the internal head name.
        let msg = format!("{}", d.errors()[0]);
        assert!(
            msg.contains("tuple[float, ...]"),
            "diagnostic should render variadic tuple as `tuple[float, ...]`; got: {}",
            msg,
        );
    }

    #[test]
    fn generator_return_no_value_accepted_against_iterator() {
        // Inside a generator, `return` is `raise StopIteration` and
        // produces no `Iterator[T]` value — the return-statement
        // validator must skip its usual assignability check
        // (FINDINGS O6).
        let src = "\
from typing import Iterator

def stop_early(n: int) -> Iterator[int]:
    for i in range(n):
        if i > 5:
            return
        yield i
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "bare `return` inside an Iterator[T] generator must be accepted; got: {:?}",
            d.errors()
        );
    }

    #[test]
    fn while_loop_test_narrows_body_for_iterator_idiom() {
        // The linked-list iterator pattern relies on `while cur is not
        // None:` narrowing `cur` to non-null at every read site inside
        // the body — including the `cur = cur.next` reassignment
        // (which reads .next on the *currently narrowed* value, then
        // resets narrowing for the new value). Without while-test
        // narrowing this is `tyc::nullable_use` on the very first
        // `cur.value` and `cur.next` read (FINDINGS O2).
        let src = "\
class Node:
    value: int
    next: Node?

def sum_list(head: Node?) -> int:
    mut total: int = 0
    mut cur: Node? = head
    while cur is not None:
        total = total + cur.value
        cur = cur.next
    return total
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "while-test narrowing must let the linked-list idiom check; got: {:?}",
            d.errors()
        );
    }

    #[test]
    fn while_loop_narrowing_resets_after_reassignment() {
        // Narrowing inside the body is sound only *until* the narrowed
        // name is reassigned. After `cur = None` the next read must
        // see `cur` as nullable again — the assignment site resets
        // narrowing exactly the way a plain `if`-narrowed branch does.
        let src = "\
class Node:
    value: int
    next: Node?

def f(head: Node?) -> int:
    mut total: int = 0
    mut cur: Node? = head
    while cur is not None:
        cur = None
        total = total + cur.value
    return total
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "post-reassignment read should still trip nullable_use"
        );
    }

    #[test]
    fn recursive_type_alias_through_constructor_is_legal() {
        // Self-referential aliases through `list[Self]` / `dict[str, Self]`
        // are the canonical recursive-JSON / AST / tree shape, and PEP 695
        // aliases are lazily evaluated, so the recursion is legal. The
        // checker must accept the alias AND the container-literal uses
        // (element expectations resolve through the alias/union).
        let src = "\
type JSON = None | bool | int | float | str | list[JSON] | dict[str, JSON]

def main() -> None:
    let x: JSON = {\"a\": [1, 2, \"three\"]}
    let y: JSON = None
    let z: JSON = [1, 2, 3]
    print(x, y, z)
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "guarded recursive alias must check cleanly; got: {:?}",
            d.errors()
        );
    }

    #[test]
    fn unguarded_alias_cycle_still_rejected() {
        // A cycle with no type constructor anywhere has no base case —
        // `type A = A | int` and the two-alias ping-pong stay errors.
        let d = check("type A = B\ntype B = A\n");
        assert!(
            d.errors().iter().any(|e| format!("{e}").contains("cycle")),
            "direct two-alias cycle must error; got: {:?}",
            d.errors()
        );
        let d2 = check("type A = A | int\n");
        assert!(
            d2.errors().iter().any(|e| format!("{e}").contains("cycle")),
            "unguarded self-union must error; got: {:?}",
            d2.errors()
        );
    }

    #[test]
    fn generator_return_with_value_accepted_against_iterator() {
        // PEP 380: `return value` inside a generator sets
        // StopIteration.value. The body is still a generator, so the
        // declared `Iterator[int]` return type is correct — the value
        // is *not* required to match that type.
        let src = "\
from typing import Iterator

def stop_early() -> Iterator[int]:
    yield 1
    return \"done\"
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "`return value` inside a generator must skip the value-against-Iterator check; got: {:?}",
            d.errors()
        );
    }

    #[test]
    fn generator_return_value_checked_against_generator_r_param() {
        // `Generator[Y, S, R]` *does* carry a declared return-payload
        // type; a `return value` inside one must be assignable to R.
        // The Iterator-shaped relaxation must not silently accept
        // mismatched payloads when the user spelled out all three
        // parameters (Codex review on PR #94).
        let ok = check(
            "\
from typing import Generator

def g() -> Generator[int, None, str]:
    yield 1
    return \"done\"
",
        );
        assert!(
            !ok.has_errors(),
            "matching `return value` against R should be accepted; got: {:?}",
            ok.errors()
        );

        let bad = check(
            "\
from typing import Generator

def g() -> Generator[int, None, str]:
    yield 1
    return 42
",
        );
        assert!(
            bad.has_errors(),
            "mismatched `return value` against R should be rejected"
        );
        let msg = format!("{}", bad.errors()[0]);
        assert!(
            msg.contains("expected `str`"),
            "diagnostic should reference R (= str); got: {}",
            msg,
        );
    }

    #[test]
    fn while_else_branch_has_negated_narrowing() {
        // `while x is not None: ... else: <here>` runs exactly when
        // the test became false — i.e. `x is None`. The else block
        // should see `x` narrowed to `None`, the dual of the body's
        // positive narrowing (Gemini review on PR #94).
        let src = "\
def f(x: int?) -> None:
    mut cur: int? = x
    while cur is not None:
        cur = None
    else:
        let n: None = cur
        return
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "negated narrowing should flow into the `while … else:` block; got: {:?}",
            d.errors()
        );
    }

    #[test]
    fn bidirectional_tuple_propagates_expected_per_slot() {
        // `tuple[list[int], list[str]] = ([], [])` should propagate each
        // slot's element type into the corresponding empty list literal.
        let src = "\
let pair: tuple[list[int], list[str]] = ([], [])
";
        let d = check(src);
        assert!(!d.has_errors(), "{:?}", d.errors());
        // Swapping the element types in the literal must now be caught.
        let bad = "\
let pair: tuple[list[int], list[str]] = ([\"x\"], [1])
";
        let d2 = check(bad);
        assert!(
            d2.has_errors(),
            "list[str] in slot 0 (expected list[int]) must be rejected"
        );
    }

    #[test]
    fn bidirectional_self_binding_does_not_block_backward_pass() {
        // `head[T](xs: list[T]) -> T` called with `[]`: the empty literal
        // is inferred under the formal `list[T]`, so the literal becomes
        // `list[T]` (carrying T forward).  Without the self-binding
        // suppression, the forward pass would record `T → T` and the
        // backward pass would be skipped, leaving the call's return as
        // the literal TypeVar T.  Verify that the annotation actually
        // drives inference by checking that an incompatible annotation is
        // rejected.
        let src = "\
def head[T](xs: list[T]) -> T:
    return xs[0]

let n: int = head([])
let s: str = head([])
let bad: int = head([\"x\"])
";
        let d = check(src);
        // The first two `let` lines must type-check (T is pinned by each
        // annotation respectively).  The third must fail: `[\"x\"]` is
        // `list[str]`, so T=str, return is str, not assignable to int.
        let errs: Vec<String> = d.errors().iter().map(|e| e.to_string()).collect();
        assert!(
            errs.iter().any(|m| m.contains("int")),
            "expected an int-vs-str mismatch on the bad assignment; errs: {errs:?}"
        );
    }

    #[test]
    fn bidirectional_pinned_typevar_still_bound_checked() {
        // `def mk[T: int]() -> T` has no args to bind T; the backward pass
        // would pin T=str from the `let s: str = mk()` annotation.  Bound
        // validation must still fire — `str` does not satisfy `T: int`.
        let src = "\
def mk[T: int]() -> T:
    return 0

let s: str = mk()
";
        let d = check(src);
        assert!(
            has_typevar_bound_error(&d),
            "T=str pinned by expected return must still violate the T: int bound; \
             errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn dict_unpack_merges_mapping_kv_not_value() {
        // `{"a": 1, **d}` where `d: dict[str, int]` must produce
        // `dict[str, int]`, not `dict[str, int | dict[str, int]]`.
        let src = "\
def take(m: dict[str, int]) -> None:
    pass

let d: dict[str, int] = {\"x\": 1}
take({\"a\": 2, **d})
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "dict unpack should merge K/V, not push the mapping into vals: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn bidirectional_empty_list_picks_up_annotation() {
        // `let xs: list[int] = []` should now type-check: the empty list
        // borrows the annotation's `int` element type.
        let src = "let xs: list[int] = []\n";
        let d = check(src);
        assert!(!d.has_errors(), "{:?}", d.errors());
    }

    #[test]
    fn bidirectional_empty_dict_picks_up_annotation() {
        let src = "let m: dict[str, int] = {}\n";
        let d = check(src);
        assert!(!d.has_errors(), "{:?}", d.errors());
    }

    #[test]
    fn list_literal_infers_element_union() {
        // `[1, "x"]` should infer `list[int | str]`, not `list[?]`.  Verify
        // by feeding it to a function whose parameter is `list[int]` and
        // checking the call is rejected.
        let src = "\
def take_ints(xs: list[int]) -> None:
    pass

take_ints([1, \"x\"])
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "list[int|str] is not assignable to list[int]"
        );
    }

    #[test]
    fn list_literal_homogeneous_passes_strict_param() {
        let src = "\
def take_ints(xs: list[int]) -> None:
    pass

take_ints([1, 2, 3])
";
        let d = check(src);
        assert!(!d.has_errors(), "{:?}", d.errors());
    }

    #[test]
    fn bidirectional_empty_arg_pins_typevar_via_param() {
        // `def head[T](xs: list[T]) -> T:` then `head([])` — without a
        // call-site annotation we have no information, so T stays unbound
        // (return ends up as the literal TypeVar T) and the call is
        // permitted (TypeVar acts as Any).  But when the parameter type
        // flows into the empty list, the literal becomes `list[T]`, and
        // bidirectional inference at the outer call should still succeed
        // when the result is assigned to a concrete type.
        let src = "\
def head[T](xs: list[T]) -> T:
    return xs[0]

let n: int = head([])
";
        let d = check(src);
        assert!(!d.has_errors(), "{:?}", d.errors());
    }

    #[test]
    fn bidirectional_return_pins_typevar_for_factory() {
        // `make[T]() -> list[T]` has no args to drive inference; the
        // call-site annotation must do it.
        let src = "\
def make[T]() -> list[T]:
    return []

let xs: list[int] = make()
";
        let d = check(src);
        assert!(!d.has_errors(), "{:?}", d.errors());
    }

    #[test]
    fn optional_param_against_concrete_arg_binds_inner() {
        // `def f[T](x: T | None) -> T` called with `int` should infer T=int,
        // not T = int|None — verified by assigning the return to `int`.
        let src = "\
def unwrap[T](x: T | None) -> T:
    if x is None:
        return x
    return x

let n: int = unwrap(3)
";
        // The body's narrowing isn't perfect, but the call-site inference
        // should still produce `int` for the return type.
        let d = check(src);
        // We only assert there's no assignment mismatch on `let n: int = unwrap(3)`.
        let has_mismatch = d.errors().iter().any(|e| {
            let msg = e.to_string();
            msg.contains("expected `int`") && msg.contains("unwrap")
        });
        assert!(
            !has_mismatch,
            "unwrap(3) should infer int, not int|None: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn pep695_inferred_return_flows_to_concrete_assignment() {
        // After inference, calling `first[T](list[T]) -> T` with `list[int]`
        // yields a return type of `int`, so assigning to a `str`-typed
        // binding must now be rejected.  Before inference this passed
        // because `T` was Any in the return position.
        let src = "\
def first[T](items: list[T]) -> T:
    return items[0]

let xs: list[int] = [1, 2, 3]
let n: str = first(xs)
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "with PEP 695 inference, first(list[int]) returns int and must not assign to str"
        );
    }

    // ── TypeVar bound checking ────────────────────────────────────────────────

    #[test]
    fn typevar_bound_subclass_satisfies_parent_class_bound() {
        // `def f[T: Animal](x: T)` called with `Dog` — `Dog` inherits from
        // `Animal`, so it satisfies the `T: Animal` bound.  No diagnostic expected.
        let src = "\
class Animal:
    pass

class Dog(Animal):
    pass

def f[T: Animal](x: T) -> T:
    return x

let d: Dog = Dog()
let r: Dog = f(d)
";
        let d = check(src);
        assert!(
            !has_typevar_bound_error(&d),
            "Dog inherits from Animal so T: Animal should be satisfied; errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn typevar_bound_unrelated_class_emits_violation() {
        // `Cat` does not inherit from `Animal`, so passing it to `f[T: Animal]`
        // must still produce a diagnostic.
        let src = "\
class Animal:
    pass

class Cat:
    pass

def f[T: Animal](x: T) -> T:
    return x

let c: Cat = Cat()
let r: Cat = f(c)
";
        let d = check(src);
        assert!(
            has_typevar_bound_error(&d),
            "Cat does not inherit from Animal so T: Animal bound should be violated; errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn typevar_bound_interface_satisfied_by_conforming_class() {
        // `def f[T: Greeter](x: T)` called with `Dog` which conforms to `Greeter`
        // structurally — must be accepted without a typevar_bound diagnostic.
        let src = "\
interface Greeter:
    def greet(self) -> str: ...

class Dog:
    def greet(self) -> str:
        return \"woof\"

def f[T: Greeter](x: T) -> T:
    return x

let d: Dog = Dog()
let r: Dog = f(d)
";
        let d = check(src);
        assert!(
            !has_typevar_bound_error(&d),
            "Dog conforms to Greeter so T: Greeter bound should be satisfied; errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    fn has_typevar_bound_error(d: &Diagnostics) -> bool {
        // The TypeVarBoundViolation message template is:
        // "type argument `{actual}` for `{typevar}` does not satisfy bound `{bound}`"
        d.errors()
            .iter()
            .any(|e| e.to_string().contains("does not satisfy bound"))
    }

    // ---- C4: variance flow through a *generic* interface bound -----------
    //
    // A generic interface `Producer[T]` / `Consumer[T]` is a type-parameter
    // bound (`def f[X: Producer[Animal]](...)`). Conformance must bind the
    // interface's `T` to the bound's argument and then honour position
    // variance: return types covariantly, parameter types contravariantly.

    #[test]
    fn typevar_generic_iface_bound_covariant_exact_match_accepted() {
        // `AnimalProducer.get -> Animal` against `Producer[Animal]`: exact.
        let src = "\
class Animal:
    pass

interface Producer[T]:
    def get(self) -> T: ...

class AnimalProducer:
    def get(self) -> Animal:
        return Animal()

def use_ap[X: Producer[Animal]](p: X) -> Animal:
    return p.get()

let ap: AnimalProducer = AnimalProducer()
let a: Animal = use_ap(ap)
";
        let d = check(src);
        assert!(
            !has_typevar_bound_error(&d),
            "exact-match producer should satisfy Producer[Animal]; errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn typevar_generic_iface_bound_covariant_subtype_accepted() {
        // `DogProducer.get -> Dog` against `Producer[Animal]` with
        // `Dog <: Animal`: covariant return, sound, accepted.
        let src = "\
class Animal:
    pass

class Dog(Animal):
    pass

interface Producer[T]:
    def get(self) -> T: ...

class DogProducer:
    def get(self) -> Dog:
        return Dog()

def use_ap[X: Producer[Animal]](p: X) -> Animal:
    return p.get()

let dp: DogProducer = DogProducer()
let a: Animal = use_ap(dp)
";
        let d = check(src);
        assert!(
            !has_typevar_bound_error(&d),
            "Dog<:Animal so DogProducer should satisfy Producer[Animal] covariantly; errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn typevar_generic_iface_bound_covariant_unrelated_return_rejected() {
        // `PlantProducer.get -> Plant` against `Producer[Animal]`: `Plant`
        // is not a subtype of `Animal`, so the covariant return position
        // is violated and the bound must be reported. Before C4 the
        // interface's `T` was left unbound (treated as `Any`) and this
        // spuriously conformed.
        let src = "\
class Animal:
    pass

class Plant:
    pass

interface Producer[T]:
    def get(self) -> T: ...

class PlantProducer:
    def get(self) -> Plant:
        return Plant()

def use_ap[X: Producer[Animal]](p: X) -> Animal:
    return p.get()

let pp: PlantProducer = PlantProducer()
let a: Animal = use_ap(pp)
";
        let d = check(src);
        assert!(
            has_typevar_bound_error(&d),
            "Plant is not Animal so PlantProducer must NOT satisfy Producer[Animal]; errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn typevar_generic_iface_bound_contravariant_supertype_accepted() {
        // `AnimalConsumer.consume(item: Animal)` against `Consumer[Dog]`:
        // a consumer of the wider `Animal` can stand in where a
        // `Consumer[Dog]` is required (contravariant parameter). Accepted.
        let src = "\
class Animal:
    pass

class Dog(Animal):
    pass

interface Consumer[T]:
    def consume(self, item: T) -> None: ...

class AnimalConsumer:
    def consume(self, item: Animal) -> None:
        pass

def use_dc[X: Consumer[Dog]](c: X) -> None:
    pass

let ac: AnimalConsumer = AnimalConsumer()
use_dc(ac)
";
        let d = check(src);
        assert!(
            !has_typevar_bound_error(&d),
            "Animal consumer should satisfy Consumer[Dog] contravariantly; errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn typevar_generic_iface_bound_contravariant_subtype_param_rejected() {
        // `DogConsumer.consume(item: Dog)` against `Consumer[Animal]`: a
        // consumer that only handles `Dog` cannot stand in where any
        // `Animal` may be passed (contravariant parameter violated).
        // Before C4 this spuriously conformed.
        let src = "\
class Animal:
    pass

class Dog(Animal):
    pass

interface Consumer[T]:
    def consume(self, item: T) -> None: ...

class DogConsumer:
    def consume(self, item: Dog) -> None:
        pass

def use_ac[X: Consumer[Animal]](c: X) -> None:
    pass

let dc: DogConsumer = DogConsumer()
use_ac(dc)
";
        let d = check(src);
        assert!(
            has_typevar_bound_error(&d),
            "Dog-only consumer must NOT satisfy Consumer[Animal] (contravariance); errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn typevar_generic_iface_bound_field_type_substituted() {
        // Field-shaped interface member: `value: T` against
        // `Holder[int]`. A class whose `value` is `str` must be rejected;
        // an `int`-valued one accepted. Exercises the field substitution
        // path of the conformance check.
        let ok = "\
interface Holder[T]:
    value: T

class IntHolder:
    value: int

    def __init__(self) -> None:
        self.value = 0

def use_holder[X: Holder[int]](h: X) -> None:
    pass

let ih: IntHolder = IntHolder()
use_holder(ih)
";
        let d = check(ok);
        assert!(
            !has_typevar_bound_error(&d),
            "int field should satisfy Holder[int]; errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );

        let bad = "\
interface Holder[T]:
    value: T

class StrHolder:
    value: str

    def __init__(self) -> None:
        self.value = \"x\"

def use_holder[X: Holder[int]](h: X) -> None:
    pass

let sh: StrHolder = StrHolder()
use_holder(sh)
";
        let d = check(bad);
        assert!(
            has_typevar_bound_error(&d),
            "str field must NOT satisfy Holder[int]; errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn typevar_bound_violated_emits_diagnostic() {
        // `def f[T: int](x: T) -> T` called with a `str` argument.
        // The bound says T must satisfy `int`; `str` is not assignable to
        // `int`, so a `tyc::typevar_bound` diagnostic must be emitted.
        let src = "\
def f[T: int](x: T) -> T:
    return x

let s: str = \"hello\"
let r: int = f(s)
";
        let d = check(src);
        assert!(
            has_typevar_bound_error(&d),
            "calling f[T: int] with str should emit a typevar_bound diagnostic; errors: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn typevar_no_bound_does_not_emit_bound_diagnostic() {
        // An unbounded typevar should never produce a typevar_bound error.
        let src = "\
def identity[T](x: T) -> T:
    return x

let s: str = \"hi\"
let r: str = identity(s)
";
        let d = check(src);
        assert!(
            !has_typevar_bound_error(&d),
            "unbounded typevar should not produce a typevar_bound diagnostic"
        );
    }

    // ── interface field type checking ────────────────────────────────────────

    #[test]
    fn interface_field_correct_type_passes() {
        let src = "\
interface Named:
    name: str

class Dog:
    name: str

let d: Named = Dog(name=\"Fido\")
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "class with correct field type should conform to interface; errors: {:?}",
            d.errors()
        );
    }

    #[test]
    fn interface_field_wrong_type_rejected() {
        // `Dog.name: int` does not satisfy `Named.name: str`.
        let src = "\
interface Named:
    name: str

class Dog:
    name: int

let d: Named = Dog(name=1)
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "class with wrong field type must not conform to interface"
        );
        let msg = format!("{}", d.errors()[0]);
        assert!(
            msg.contains("Named") || msg.contains("name"),
            "diagnostic should mention the interface or field; got: {msg}"
        );
    }

    #[test]
    fn interface_field_missing_rejected() {
        // `Dog` is missing the `name` field entirely.
        let src = "\
interface Named:
    name: str

class Dog:
    age: int

let d: Named = Dog(age=1)
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "class missing required interface field must be rejected"
        );
        let msg = format!("{}", d.errors()[0]);
        assert!(
            msg.contains("name") || msg.contains("Named"),
            "diagnostic should name the missing field; got: {msg}"
        );
    }

    #[test]
    fn interface_field_mismatch_diagnostic_names_types() {
        // The diagnostic text should include both the expected and actual types.
        let src = "\
interface Config:
    port: int

class BadConfig:
    port: str

let c: Config = BadConfig(port=\"oops\")
";
        let d = check(src);
        assert!(d.has_errors(), "type-mismatched field must be rejected");
        let msg = format!("{}", d.errors()[0]);
        // The conformance error wraps field mismatches; the outer message names the interface.
        assert!(
            msg.contains("Config") || msg.contains("port"),
            "diagnostic should reference the interface or field name; got: {msg}"
        );
    }

    #[test]
    fn interface_field_accepts_conforming_class_for_interface_typed_field() {
        // When an interface field's type is itself an interface, a concrete class
        // that structurally conforms to that nested interface should be accepted.
        // This requires `self.is_assignable` (not the free `assignable`) so the
        // structural conformance check fires.
        let src = "\
interface Pet:
    name: str

interface Owner:
    pet: Pet

class Dog:
    name: str

class Person:
    pet: Dog

let p: Owner = Person(pet=Dog(name=\"Fido\"))
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "concrete class satisfying nested interface field should conform; errors: {:?}",
            d.errors()
        );
    }

    #[test]
    fn interface_field_satisfied_by_zero_arity_method_passes() {
        // A zero-argument method (property-like) may satisfy an interface field.
        // In Typhon's class shape, `def name(self)` records arity 0 (self excluded).
        let src = "\
interface Named:
    name: str

class Dog:
    def name(self) -> str:
        return \"Fido\"

let d: Named = Dog()
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "zero-arity method should satisfy interface field; errors: {:?}",
            d.errors()
        );
    }

    #[test]
    fn interface_field_satisfied_by_nonzero_arity_method_rejected() {
        // A method with arguments must NOT satisfy an interface field requirement.
        let src = "\
interface Named:
    name: str

class Dog:
    def name(self, suffix: str) -> str:
        return \"Fido\" + suffix

let d: Named = Dog()
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "method with arguments must not satisfy interface field; should be rejected"
        );
    }

    #[test]
    fn interface_method_return_type_mismatch_rejected() {
        let src = "\
interface Greeter:
    def greet(self) -> str: ...

class BadGreeter:
    def greet(self) -> int:
        return 42

let g: Greeter = BadGreeter()
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "method with wrong return type should fail interface conformance; errors: {:?}",
            d.errors()
        );
    }

    #[test]
    fn interface_method_return_type_match_passes() {
        let src = "\
interface Greeter:
    def greet(self) -> str: ...

class GoodGreeter:
    def greet(self) -> str:
        return \"hello\"

let g: Greeter = GoodGreeter()
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "method with matching return type should pass interface conformance; errors: {:?}",
            d.errors()
        );
    }

    #[test]
    fn interface_method_unannotated_impl_now_rejected_by_rule_one() {
        // Rule 1 (every parameter and return type annotated) is now
        // enforced, so an unannotated `def greet(self):` is itself a
        // diagnostic before conformance is ever consulted. The conformance
        // path that treats `Type::Unknown` permissively still exists for
        // compiler-synthesised stubs; it just can't be reached through
        // user source without violating Rule 1.
        let src = "\
interface Greeter:
    def greet(self) -> str: ...

class BareGreeter:
    def greet(self):
        return \"hello\"

let g: Greeter = BareGreeter()
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "Rule 1 should reject the unannotated `greet` impl; errors: {:?}",
            d.errors()
        );
        assert!(
            d.errors()
                .iter()
                .any(|e| format!("{e}").contains("missing a type annotation")),
            "expected a missing_annotation diagnostic; got: {:?}",
            d.errors()
        );
    }

    // ── Attribute resolution: class instances and TypeVar-bounded params ──────

    #[test]
    fn class_instance_method_call_type_checks() {
        let src = "\
class Greeter:
    def greet(self) -> str:
        return \"hello\"

let g: Greeter = Greeter()
let result: str = g.greet()
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "method call on class instance should type-check: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn typevar_bound_body_method_call_checks() {
        // Inside the function body, x: T where T: Greeter — x.greet() must be valid
        let src = "\
interface Greeter:
    def greet(self) -> str: ...

def call_greet[T: Greeter](x: T) -> str:
    return x.greet()
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "x.greet() on T: Greeter should type-check: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn typevar_bound_body_unknown_method_emits_error() {
        // x.nonexistent() on T: Greeter must emit attribute_not_found
        let src = "\
interface Greeter:
    def greet(self) -> str: ...

def call_bad[T: Greeter](x: T) -> str:
    return x.nonexistent()
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "x.nonexistent() on T: Greeter should emit attribute_not_found"
        );
        assert!(
            d.errors()
                .iter()
                .any(|e| e.to_string().contains("nonexistent")),
            "error should mention the missing attribute"
        );
    }

    #[test]
    fn typevar_bound_body_field_access_works() {
        // x.name where T: Named (interface with field name: str) must work
        let src = "\
interface Named:
    name: str

def get_name[T: Named](x: T) -> str:
    return x.name
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "field access on T: Named should type-check: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    // ── E2: impl methods accept T? parameters ────────────────────────────────

    #[test]
    fn impl_method_accepts_nullable_arg_and_none() {
        // FINDINGS E2: `impl X: def f(self, p: str?)` rejected `None`
        // and `str?` arguments because the method's `param_types`
        // weren't recorded — they fell back to `Type::Unknown`, and
        // the call site's nullable-into-non-nullable guard misfired.
        let src = "\
class API:
    name: str

impl API:
    def fetch(self, cursor: str?) -> int:
        return 0 if cursor is None else len(cursor)

def main() -> None:
    let api: API = API(name=\"x\")
    let v: str? = None
    let n1: int = api.fetch(v)
    let n2: int = api.fetch(None)
    let n3: int = api.fetch(\"hi\")
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "impl method with `T?` param must accept `T?` / `None`: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    // ── E3: `return self` from impl `__enter__` carries the real class type ──

    #[test]
    fn impl_return_self_uses_real_class_name() {
        // FINDINGS E3: the impl block desugars to `__typhon_impl_X`;
        // the type checker was previously typing `self` as
        // `__typhon_impl_X` so `return self` against `-> X` failed.
        let src = "\
class Stopwatch:
    start: float

impl Stopwatch:
    def enter(self) -> Stopwatch:
        return self
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "return self from impl method must match declared class type: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    // ── E4: type-alias of Callable unwraps on call ──────────────────────────

    #[test]
    fn callable_type_alias_call_returns_alias_target() {
        // FINDINGS E4: `type Handler = Callable[[Req], Resp]` followed
        // by `next(req)` typed the return as `Handler` not `Resp`.
        let src = "\
from typing import Callable

class Req:
    n: int

class Resp:
    s: str

type Handler = Callable[[Req], Resp]

def call(h: Handler, r: Req) -> Resp:
    return h(r)
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "calling a value typed as a Callable alias must return the alias target: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    // ── E5: __mul__ / __add__ overrides resolve to user-declared return ──────

    #[test]
    fn binop_resolves_user_dunder_over_numeric_fallback() {
        // FINDINGS E5: `Vec2(...) * 5.0` resolved to `Float` via the
        // numeric-coercion rule even though `Vec2` defined
        // `__mul__(self, scalar: float) -> Vec2`. The dunder lookup
        // now takes precedence over the conservative numeric
        // inference table.
        let src = "\
class Vec2:
    x: float
    y: float

impl Vec2:
    def __mul__(self, scalar: float) -> Vec2:
        return Vec2(x=self.x * scalar, y=self.y * scalar)
    def __add__(self, other: Vec2) -> Vec2:
        return Vec2(x=self.x + other.x, y=self.y + other.y)

def go() -> None:
    let a: Vec2 = Vec2(x=1.0, y=2.0)
    let b: Vec2 = Vec2(x=3.0, y=4.0)
    let sum: Vec2 = a + b
    let scaled: Vec2 = a * 5.0
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "user-defined __mul__/__add__ must drive BinOp result type: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn binop_dunder_rejects_arg_type_mismatch() {
        // codex review on PR #87: previously, the dunder return type
        // was adopted whenever the dunder method existed, even if the
        // RHS didn't match the dunder's declared formal. `v * "bad"`
        // for `def __mul__(self, scalar: float) -> Vec2` must surface
        // an operator type mismatch, not silently infer `Vec2`.
        let src = "\
class V:
    x: float

impl V:
    def __mul__(self, scalar: float) -> V:
        return V(x=self.x * scalar)

def main() -> None:
    let v: V = V(x=1.0)
    let r: V = v * \"bad\"
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "v * \"bad\" must surface a diagnostic when __mul__ expects a float, got: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    // ── E6: exhaustiveness recognises positional class patterns ──────────────

    #[test]
    fn positional_class_pattern_counts_as_total_match() {
        // FINDINGS E6: `case Leaf(value):` (positional capture of every
        // field) was not treated as covering the `Leaf` variant of a
        // sealed union, so `missing_return` fired on otherwise-total
        // matches.
        let src = "\
class Leaf:
    value: int

class Branch:
    left: Leaf
    right: Leaf

type Tree = Leaf | Branch

def first(t: Tree) -> int:
    match t:
        case Leaf(value):
            return value
        case Branch(left, right):
            return left.value
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "positional class pattern must count as a total match for that variant: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn shorter_positional_pattern_still_covers_variant() {
        // copilot review on PR #87: `case Branch(left):` (one
        // positional capture for a class with two declared fields)
        // is a valid pattern at parse time and should count as a
        // total match for the Branch variant of a sealed union —
        // the omitted positional is unconstrained at runtime.
        let src = "\
class Leaf:
    value: int

class Branch:
    left: Leaf
    right: Leaf

type Tree = Leaf | Branch

def go(t: Tree) -> int:
    match t:
        case Leaf(value):
            return value
        case Branch(left):
            return left.value
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "shorter positional pattern must count as a total match: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    // ── frozen-class field-write rejection ───────────────────────────────────

    #[test]
    fn rejects_direct_write_to_frozen_field() {
        let src = "\
class Identity frozen:
    name: str

let i: Identity = Identity(name=\"Alice\")
i.name = \"Bob\"
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "direct write to a frozen field must be rejected"
        );
        assert!(
            d.errors()
                .iter()
                .any(|e| e.to_string().contains("frozen") && e.to_string().contains("name")),
            "diagnostic should name the frozen field: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn rejects_nested_write_to_frozen_field() {
        // The exact case from the user's bug report: a frozen field is
        // reached through one or more attribute hops from a mutable
        // container. The receiver `outer.inner` resolves to a frozen
        // class, so the final write must be rejected.
        let src = "\
class Identity frozen:
    name: str

class User:
    identity: Identity
    age: int

let user: User = User(identity=Identity(name=\"Alice\"), age=30)
user.identity.name = \"Bob\"
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "nested write to a frozen field must be rejected"
        );
    }

    #[test]
    fn rejects_aug_assign_to_frozen_field() {
        let src = "\
class Counter frozen:
    n: int

let c: Counter = Counter(n=0)
c.n += 1
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "augmented assignment to a frozen field must be rejected"
        );
    }

    #[test]
    fn rejects_self_write_inside_impl_of_frozen_class() {
        // The user can still write `impl FrozenClass: def m(self): self.x = ...`;
        // we want the same diagnostic to fire there, not just at outside
        // call sites.
        let src = "\
class Identity frozen:
    name: str

impl Identity:
    def rename(self, new_name: str) -> None:
        self.name = new_name
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "self-write inside impl of frozen class must be rejected"
        );
        // The diagnostic should display the original class name, not the
        // `__typhon_impl_*` pseudo-class name.
        assert!(
            d.errors()
                .iter()
                .any(|e| e.to_string().contains("`Identity`")),
            "diagnostic should display the user-visible class name `Identity`, not the pseudo: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn allows_write_to_mutable_class_field() {
        let src = "\
class User:
    name: str

impl User:
    def rename(self, new_name: str) -> None:
        self.name = new_name

let u: User = User(name=\"Alice\")
u.name = \"Bob\"
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "writes to mutable class fields must still pass: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn allows_field_declarations_in_frozen_class_body() {
        // `class X frozen:` field annotations (`name: str`) are
        // declarations, not assignments — they must not be flagged.
        let src = "\
class Identity frozen:
    name: str
    age: int = 0
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "field declarations inside a frozen class body must not be flagged: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    // ── async_without_await ───────────────────────────────────────────────

    fn has_async_without_await_warning(d: &Diagnostics) -> bool {
        d.warnings().iter().any(|w: &TycError| {
            let s = w.to_string();
            s.contains("async_without_await") || s.contains("no `await`")
        })
    }

    #[test]
    fn async_without_await_warns_on_bare_async_def() {
        let d = check("async def foo():\n    x: int = 1\n");
        assert!(
            has_async_without_await_warning(&d),
            "expected async_without_await warning, got: {:?}",
            d.warnings()
                .iter()
                .map(|w: &TycError| w.to_string())
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn async_without_await_silent_when_await_present() {
        let d = check("async def fetch() -> int:\n    x = await some_coro()\n    return x\n");
        assert!(
            !has_async_without_await_warning(&d),
            "unexpected async_without_await warning: {:?}",
            d.warnings()
                .iter()
                .map(|w: &TycError| w.to_string())
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn async_without_await_not_triggered_by_await_in_nested_def() {
        // An `await` that lives inside an inner `async def` does not count
        // toward the outer function's await detection.
        let d = check("async def outer():\n    async def inner():\n        await some_coro()\n");
        assert!(
            has_async_without_await_warning(&d),
            "outer should warn because its own body has no await; got: {:?}",
            d.warnings()
                .iter()
                .map(|w: &TycError| w.to_string())
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn async_without_await_silent_for_async_for() {
        // `async for` counts as an asynchronous construct — no warning expected.
        let d = check("async def consume(ait):\n    async for item in ait:\n        pass\n");
        assert!(
            !has_async_without_await_warning(&d),
            "async for should suppress async_without_await; got: {:?}",
            d.warnings()
                .iter()
                .map(|w: &TycError| w.to_string())
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn async_without_await_silent_for_async_with() {
        // `async with` counts as an asynchronous construct — no warning expected.
        let d = check("async def managed(cm):\n    async with cm as ctx:\n        pass\n");
        assert!(
            !has_async_without_await_warning(&d),
            "async with should suppress async_without_await; got: {:?}",
            d.warnings()
                .iter()
                .map(|w: &TycError| w.to_string())
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn async_without_await_suppressed_for_async_interface_impl() {
        // A trivial impl of an async `interface` method must stay `async`
        // to structurally conform, even when it awaits nothing — so the
        // warning is a false positive and is suppressed. The motivating
        // case from the field report: `ConsoleSink.deliver` only prints.
        let src = "\
interface Sink:
    async def deliver(self, msg: str) -> None

class ConsoleSink:
    prefix: str

impl ConsoleSink:
    async def deliver(self, msg: str) -> None:
        print(self.prefix + msg)
";
        let d = check(src);
        assert!(
            !has_async_without_await_warning(&d),
            "async impl of an async interface method should suppress async_without_await; got: {:?}",
            d.warnings()
                .iter()
                .map(|w: &TycError| w.to_string())
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn async_without_await_suppressed_for_async_base_override() {
        // Overriding an async base-class method must stay `async`; a
        // trivial awaitless override is required, not a mistake. The base
        // method itself awaits, so only the override exercises the
        // carve-out.
        let src = "\
import asyncio

class Base:
    pass

impl Base:
    async def run(self) -> None:
        await asyncio.sleep(0)

class Worker(Base):
    pass

impl Worker:
    async def run(self) -> None:
        print(\"working\")
";
        let d = check(src);
        assert!(
            !has_async_without_await_warning(&d),
            "awaitless override of an async base method should suppress async_without_await; got: {:?}",
            d.warnings()
                .iter()
                .map(|w: &TycError| w.to_string())
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn async_without_await_still_warns_for_awaitless_method_without_contract() {
        // Guard against over-suppression: a method matching no async
        // interface and overriding no async base method is still flagged.
        let src = "\
class Service:
    name: str

impl Service:
    async def ping(self) -> None:
        print(self.name)
";
        let d = check(src);
        assert!(
            has_async_without_await_warning(&d),
            "an awaitless async method with no async contract should still warn; got: {:?}",
            d.warnings()
                .iter()
                .map(|w: &TycError| w.to_string())
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn async_without_await_warns_when_interface_method_is_sync() {
        // The carve-out is gated on the *interface* method being async. A
        // SYNC interface method implemented by an `async` impl is async by
        // choice, not by contract, so the awaitless warning still applies.
        let src = "\
interface Handler:
    def handle(self, msg: str) -> None

class Logger:
    pass

impl Logger:
    async def handle(self, msg: str) -> None:
        print(msg)
";
        let d = check(src);
        assert!(
            has_async_without_await_warning(&d),
            "async impl of a sync interface method should still warn; got: {:?}",
            d.warnings()
                .iter()
                .map(|w: &TycError| w.to_string())
                .collect::<Vec<_>>()
        );
    }

    // ── Phase 5.2: `or` / `and` typing ────────────────────────────────────

    #[test]
    fn or_returns_truthy_lhs_unioned_with_rhs() {
        // The motivating case: a Telegram-style `update.text or ""` pattern
        // where `text: str | None` should produce `str` after the `or`, not
        // `bool`. Without the truthy-LHS rule this binds `bool` to a `str`
        // annotation and errors.
        let src = "\
class Update:
    text: str | None

def handle(update: Update) -> None:
    let s: str = update.text or \"\"
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "`str | None or str` should infer as `str`; got: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn or_keeps_bool_when_both_sides_bool() {
        // The legacy behaviour (BoolOp -> Bool) must still hold for the
        // common `flag or default` shape where both operands are booleans.
        let src = "\
def f(a: bool, b: bool) -> None:
    let c: bool = a or b
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "`bool or bool` should still be `bool`; got: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn and_widens_to_union() {
        // `a and b` evaluates to `a` when falsy, else `b`. The conservative
        // union widening means a same-type `and` keeps the type — assigning
        // `int and int` to an `int` annotation must NOT error.
        let src = "\
def f(a: int, b: int) -> None:
    let c: int = a and b
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "`int and int` should be `int`; got: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    #[test]
    fn or_chain_regression_maybe_str_or_default() {
        // End-to-end pipeline regression: the canonical Phase 5.2 motivating
        // example. Reads as a free-standing module so the resolver, type
        // narrower, and BoolOp inference all participate.
        let src = "\
let maybe_str: str | None = None
let s: str = maybe_str or \"default\"
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "Phase 5.2 regression: `(str | None) or str` should be `str`; got: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    // ── Phase 5.2: Generator → Iterable conformance ───────────────────────

    #[test]
    fn generator_assignable_to_iterable_of_same_element() {
        // `Generator[int, None, None]` should satisfy `Iterable[int]` — the
        // shape `yield`-bodies most often have.
        let g = Type::Generic("Generator".into(), vec![Type::Int, Type::None, Type::None]);
        let it = Type::Generic("Iterable".into(), vec![Type::Int]);
        assert!(
            assignable(&it, &g),
            "Generator[int, ...] should be assignable to Iterable[int]"
        );
    }

    #[test]
    fn generator_assignable_to_iterator() {
        // `Iterator[T]` is the other common return annotation.
        let g = Type::Generic("Generator".into(), vec![Type::Str, Type::None, Type::None]);
        let it = Type::Generic("Iterator".into(), vec![Type::Str]);
        assert!(
            assignable(&it, &g),
            "Generator[str, ...] should be assignable to Iterator[str]"
        );
    }

    #[test]
    fn async_generator_assignable_to_async_iterable() {
        let ag = Type::Generic("AsyncGenerator".into(), vec![Type::Int, Type::None]);
        let ait = Type::Generic("AsyncIterable".into(), vec![Type::Int]);
        let aiter = Type::Generic("AsyncIterator".into(), vec![Type::Int]);
        assert!(
            assignable(&ait, &ag),
            "AsyncGenerator[int, ...] should be assignable to AsyncIterable[int]"
        );
        assert!(
            assignable(&aiter, &ag),
            "AsyncGenerator[int, ...] should be assignable to AsyncIterator[int]"
        );
    }

    #[test]
    fn generator_function_returning_iterable_type_checks() {
        // Full pipeline: a `yield`-bodied function annotated as
        // `Iterable[int]` must not error. Without the conformance rule the
        // body infers as `Generator[int, ...]` and fails the return check.
        let src = "\
def numbers() -> Iterable[int]:
    yield 1
    yield 2
";
        let d = check(src);
        assert!(
            !d.has_errors(),
            "yield-bodied -> Iterable[int] should type-check; got: {:?}",
            d.errors().iter().map(|e| e.to_string()).collect::<Vec<_>>()
        );
    }

    // ── O14 (unsafe value leak) — scope robustness (PR #96 review) ────────

    #[test]
    fn unsafe_leak_fires_on_baseline_repro() {
        // The motivating O14 case: a binding declared inside `unsafe:`
        // returns into a concrete `-> int` without re-assertion.
        let src = "\
def f() -> int:
    unsafe:
        let x = \"hello\"
    return x
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::UnsafeValueLeak { .. })),
            "expected UnsafeValueLeak, got {:?}",
            d.errors()
        );
    }

    #[test]
    fn unsafe_leak_silenced_by_safe_rebind() {
        // PR #96 review (Gemini, Copilot): a safe-scope rebind of the
        // same name with a compatible declared type must defeat the
        // leak audit. The user explicitly re-asserts the type at the
        // boundary; the diagnostic must not fire.
        let src = "\
def f() -> int:
    unsafe:
        let value = \"hello\"
    let checked: int = 42
    return checked
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::UnsafeValueLeak { .. })),
            "safe-scope rebind must defeat the leak audit; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn unsafe_leak_does_not_cross_function_boundary() {
        // PR #96 review (Gemini): an unsafe binding in function `f`
        // must NOT trigger a leak diagnostic in function `g` that
        // happens to use the same variable name. `unsafe_origin_bindings`
        // is now scope-saved at function entry and restored on exit.
        let src = "\
def f() -> int:
    unsafe:
        let x = \"hello\"
    return 0

def g(x: int) -> int:
    return x
";
        let d = check(src);
        // The leak should fire in `f` only — there's a `return 0`
        // there, not `return x`, so even `f` is clean. The key
        // assertion is that `g`'s `return x` doesn't fire a leak.
        let leak_in_g = d.errors().iter().any(|e| match e {
            TycError::UnsafeValueLeak { .. } => format!("{e}").contains("`x`"),
            _ => false,
        });
        // `g` has no unsafe context whatsoever — the audit must stay silent.
        assert!(
            !leak_in_g,
            "unsafe origin bindings must not bleed across function boundaries; got {:?}",
            d.errors()
        );
    }

    // ── O16 (Protocol vs built-ins) — hashability soundness (PR #96 review)

    #[test]
    fn list_does_not_satisfy_hashable_protocol() {
        // PR #96 review (Codex, Copilot, Gemini): `list` is unhashable
        // at runtime (`hash([])` raises `TypeError`). The Protocol
        // structural-conformance check must NOT accept `list[T]` for
        // a `Hashable`-like Protocol that requires `__hash__`.
        let src = "\
from typing import Protocol

class Hashable(Protocol):
    def __hash__(self) -> int: ...

def take(h: Hashable) -> int:
    return 0

let _: int = take([1, 2, 3])
";
        let d = check(src);
        assert!(
            d.has_errors(),
            "list must not satisfy a Hashable Protocol; got no errors"
        );
    }

    #[test]
    fn frozenset_does_satisfy_hashable_protocol() {
        // Counterpart: `frozenset` is hashable and must still satisfy
        // a `Hashable`-like Protocol.
        let src = "\
from typing import Protocol

class Hashable(Protocol):
    def __hash__(self) -> int: ...

def take(h: Hashable) -> int:
    return 0

let _: int = take(frozenset([1, 2, 3]))
";
        let d = check(src);
        assert!(
            !d.errors().iter().any(|e| matches!(
                e,
                TycError::TypeMismatch { .. } | TycError::InterfaceNotConforming { .. }
            )),
            "frozenset must satisfy Hashable; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn unsafe_leak_silenced_by_inner_annotation() {
        // Workaround form A: annotating the unsafe binding with the
        // concrete return type defeats the leak audit because the
        // declared type is already assignable to the return type.
        let src = "\
def f() -> int:
    unsafe:
        let x: int = 42
    return x
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::UnsafeValueLeak { .. })),
            "inner-annotated unsafe binding must not trigger the leak; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn unsafe_leak_fires_on_annotated_assignment() {
        // ITEM 3 / Rule 5: an `unsafe:`-origin value flowing into a
        // concrete-typed annotated binding (`let n: int = v`) without a
        // re-assertion must fire `tyc::unsafe_value_leak`. Previously the
        // audit only covered `return v`, so this assignment leak passed
        // `tyc check` and crashed at runtime.
        let src = "\
def main() -> None:
    unsafe:
        let v = \"not a number\"
    let n: int = v
    print(n + 1)
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::UnsafeValueLeak { .. })),
            "unsafe value leaking into `let n: int = v` must fire; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn unsafe_leak_assignment_silenced_by_object_target() {
        // `let n: object = v` is a sound widening — `object` accepts any
        // value — so the assignment leak audit must stay silent.
        let src = "\
def main() -> None:
    unsafe:
        let v = \"not a number\"
    let n: object = v
    print(n)
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::UnsafeValueLeak { .. })),
            "object target must not trigger the assignment leak; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn unsafe_leak_assignment_silenced_by_inner_annotation() {
        // Re-asserting the type inside the `unsafe:` block (or via a
        // safe-scope binding) defeats the assignment-leak audit.
        let src = "\
def main() -> None:
    unsafe:
        let v = \"not a number\"
        let checked: int = int(v)
    let n: int = checked
    print(n + 1)
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::UnsafeValueLeak { .. })),
            "re-asserted unsafe value must not trigger the assignment leak; got {:?}",
            d.errors()
        );
    }

    // ── ITEM 1: `**kwargs: T` value type-checking ────────────────────────

    #[test]
    fn kwargs_value_type_mismatch_is_rejected() {
        // A keyword argument absorbed by `**kwargs: int` must have a
        // value assignable to `int`. Pre-fix this was unchecked and the
        // bad `str` value only crashed at runtime.
        let src = "\
def f(**kwargs: int) -> None:
    print(len(kwargs))
def main() -> None:
    f(a=1, b=\"oops\")
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { expected, .. } if expected == "int")),
            "**kwargs: int must reject a str value; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn kwargs_value_type_match_is_clean() {
        // Every kwarg value assignable to the `**kwargs` element type
        // must pass cleanly.
        let src = "\
def f(**kwargs: int) -> None:
    print(len(kwargs))
def main() -> None:
    f(a=1, b=2)
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "**kwargs: int must accept int values; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn kwargs_object_value_accepts_anything() {
        // `**kwargs: object` is the canonical "accept anything" idiom.
        let src = "\
def f(**kwargs: object) -> None:
    print(len(kwargs))
def main() -> None:
    f(a=1, b=\"oops\", c=3.0)
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "**kwargs: object must accept any value; got {:?}",
            d.errors()
        );
    }

    // ── ITEM 2: contravariant Callable parameters ────────────────────────

    #[test]
    fn callable_param_contravariance_is_accepted() {
        // Passing a function with a MORE GENERAL parameter type where a
        // more specific one is expected is sound (params contravariant):
        // `Callable[[Animal], str]` is assignable to `Callable[[Dog], str]`.
        let src = "\
class Animal:
    name: str
class Dog(Animal):
    breed: str
def apply(f: Callable[[Dog], str], d: Dog) -> str:
    return f(d)
def animal_name(a: Animal) -> str:
    return a.name
def main() -> None:
    print(apply(animal_name, Dog(name=\"Rex\", breed=\"Lab\")))
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "contravariant Callable param must be accepted; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn callable_param_covariance_is_rejected() {
        // The unsound direction must still be rejected: a function that
        // only accepts `Dog` cannot stand in where any `Animal` may be
        // passed (`Callable[[Dog], str]` is NOT assignable to
        // `Callable[[Animal], str]`).
        let src = "\
class Animal:
    name: str
class Dog(Animal):
    breed: str
def apply(f: Callable[[Animal], str], a: Animal) -> str:
    return f(a)
def dog_breed(d: Dog) -> str:
    return d.breed
def main() -> None:
    print(apply(dog_breed, Animal(name=\"Rex\")))
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "covariant Callable param must be rejected; got {:?}",
            d.errors()
        );
    }

    // ── C2: user-generic variance inference tests ────────────────────────

    /// Parse `src`, take its first `class` declaration, and run the C2
    /// inference pass over it. Returns the per-type-parameter variance
    /// vector positionally aligned with the class's declared parameters.
    fn infer_variance_of_first_class(src: &str) -> Vec<Variance> {
        let prep = preprocess(src);
        let module = tyc_syntax::parse_module(&prep.python_source)
            .unwrap()
            .into_syntax();
        let classes: Vec<String> = module
            .body
            .iter()
            .filter_map(|s| match s {
                Stmt::ClassDef(cd) => Some(cd.name.as_str().to_owned()),
                _ => None,
            })
            .collect();
        let cd = module
            .body
            .iter()
            .find_map(|s| match s {
                Stmt::ClassDef(cd) => Some(cd),
                _ => None,
            })
            .expect("a class declaration");
        let tps = type_param_names_from(cd.type_params.as_deref());
        infer_class_param_variance(cd, &tps, &classes)
    }

    #[test]
    fn variance_algebra_compose_and_join() {
        // Composition: contravariant ∘ contravariant flips back to
        // covariant; anything through an invariant slot is invariant.
        assert_eq!(
            compose_variance(Variance::Covariant, Variance::Covariant),
            Variance::Covariant
        );
        assert_eq!(
            compose_variance(Variance::Contravariant, Variance::Contravariant),
            Variance::Covariant
        );
        assert_eq!(
            compose_variance(Variance::Contravariant, Variance::Covariant),
            Variance::Contravariant
        );
        assert_eq!(
            compose_variance(Variance::Covariant, Variance::Invariant),
            Variance::Invariant
        );
        // Join: same direction sticks, opposite directions collapse to
        // invariant.
        assert_eq!(
            join_variance(Variance::Covariant, Variance::Covariant),
            Variance::Covariant
        );
        assert_eq!(
            join_variance(Variance::Covariant, Variance::Contravariant),
            Variance::Invariant
        );
    }

    #[test]
    fn infers_covariant_for_output_only_param() {
        // `T` only ever flows OUT (a method return) → covariant.
        let v = infer_variance_of_first_class(
            "\
class Producer[T]:
    def get(self) -> T:
        ...
",
        );
        assert_eq!(v, vec![Variance::Covariant]);
    }

    #[test]
    fn infers_contravariant_for_input_only_param() {
        // `T` only ever flows IN (a method parameter) → contravariant.
        let v = infer_variance_of_first_class(
            "\
class Consumer[T]:
    def accept(self, item: T) -> None:
        ...
",
        );
        assert_eq!(v, vec![Variance::Contravariant]);
    }

    #[test]
    fn infers_invariant_for_param_used_in_both_positions() {
        // `T` flows both in (parameter) and out (return) → invariant.
        let v = infer_variance_of_first_class(
            "\
class Channel[T]:
    def put(self, item: T) -> None:
        ...
    def take(self) -> T:
        ...
",
        );
        assert_eq!(v, vec![Variance::Invariant]);
    }

    #[test]
    fn infers_invariant_for_settable_field() {
        // A plain annotated field is settable on the emitted dataclass →
        // invariant. This is exactly why `Box[T]` must stay invariant.
        let v = infer_variance_of_first_class(
            "\
class Box[T]:
    value: T
",
        );
        assert_eq!(v, vec![Variance::Invariant]);
    }

    #[test]
    fn infers_invariant_behind_mutable_list_field() {
        // `T` appears only in a method return, but BEHIND a mutable
        // `list[T]` — the list element slot is invariant, so the whole
        // parameter is forced invariant even though the position is output.
        let v = infer_variance_of_first_class(
            "\
class Bag[T]:
    def items(self) -> list[T]:
        ...
",
        );
        assert_eq!(v, vec![Variance::Invariant]);
    }

    #[test]
    fn infers_covariant_behind_sequence_return() {
        // A read-only `Sequence[T]` element slot is covariant, so an
        // output-position `Sequence[T]` keeps `T` covariant.
        let v = infer_variance_of_first_class(
            "\
class Source[T]:
    def items(self) -> Sequence[T]:
        ...
",
        );
        assert_eq!(v, vec![Variance::Covariant]);
    }

    #[test]
    fn unused_param_defaults_to_invariant() {
        // A phantom parameter that never appears in a classified position
        // stays invariant — the sound default.
        let v = infer_variance_of_first_class(
            "\
class Phantom[T]:
    def noop(self) -> None:
        ...
",
        );
        assert_eq!(v, vec![Variance::Invariant]);
    }

    #[test]
    fn explicit_covariant_decorator_overrides_inference() {
        // `@covariant` forces covariance even though `T` is used as an
        // input (which would otherwise infer contravariant).
        let v = infer_variance_of_first_class(
            "\
@covariant
class Forced[T]:
    def accept(self, item: T) -> None:
        ...
",
        );
        assert_eq!(v, vec![Variance::Covariant]);
    }

    #[test]
    fn covariant_user_generic_accepts_upcast() {
        // End-to-end: a covariant `Producer[Dog]` flows into a
        // `Producer[Animal]` slot.
        let src = "\
class Animal:
    name: str
class Dog(Animal):
    name: str
class Producer[T]:
    def get(self) -> T:
        ...
def use_animals(p: Producer[Animal]) -> None:
    ...
def main(dogs: Producer[Dog]) -> None:
    use_animals(dogs)
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "covariant Producer[Dog] -> Producer[Animal] must be accepted; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn contravariant_user_generic_accepts_reversed_assignment() {
        // A contravariant `Consumer[Animal]` flows into a `Consumer[Dog]`
        // slot — the reversed (sound) direction.
        let src = "\
class Animal:
    name: str
class Dog(Animal):
    name: str
class Consumer[T]:
    def accept(self, item: T) -> None:
        ...
def needs_dog_consumer(c: Consumer[Dog]) -> None:
    ...
def main(any_consumer: Consumer[Animal]) -> None:
    needs_dog_consumer(any_consumer)
";
        let d = check(src);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "contravariant Consumer[Animal] -> Consumer[Dog] must be accepted; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn invariant_user_generic_rejects_upcast() {
        // `Box[T]` has a settable field `value: T`, so it is invariant: a
        // `Box[Dog]` must NOT flow into a `Box[Animal]` slot.
        let src = "\
class Animal:
    name: str
class Dog(Animal):
    name: str
class Box[T]:
    value: T
def use_animal_box(b: Box[Animal]) -> None:
    ...
def main(dog_box: Box[Dog]) -> None:
    use_animal_box(dog_box)
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "invariant Box[Dog] -> Box[Animal] must be rejected; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn covariant_user_generic_still_rejects_downcast() {
        // Soundness floor: even a covariant `Producer` must reject the
        // WRONG direction — `Producer[Animal]` does not flow into a
        // `Producer[Dog]` slot.
        let src = "\
class Animal:
    name: str
class Dog(Animal):
    name: str
class Producer[T]:
    def get(self) -> T:
        ...
def needs_dog_producer(p: Producer[Dog]) -> None:
    ...
def main(animals: Producer[Animal]) -> None:
    needs_dog_producer(animals)
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "covariant Producer[Animal] -> Producer[Dog] must still be rejected; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn builtin_container_variance_unchanged_by_user_inference() {
        // The C2 inference must not perturb built-in heads: mutable `list`
        // stays invariant, read-only `Sequence` stays covariant, and the
        // user-aware lookup falls back to the built-in table for them.
        assert_eq!(generic_param_variance("list", 0), Variance::Invariant);
        assert_eq!(generic_param_variance("Sequence", 0), Variance::Covariant);
        assert_eq!(
            generic_param_variance("Callable", 0),
            Variance::Contravariant
        );
        assert_eq!(generic_param_variance("Callable", 1), Variance::Covariant);
        // A mutable `list[Dog]` must still NOT flow into `list[Animal]`.
        let src = "\
class Animal:
    name: str
class Dog(Animal):
    name: str
def use_animals(xs: list[Animal]) -> None:
    ...
def main(dogs: list[Dog]) -> None:
    use_animals(dogs)
";
        let d = check(src);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "list invariance must be preserved (list[Dog] -/-> list[Animal]); got {:?}",
            d.errors()
        );
    }

    // ── Cross-module variance / HKT (deferred C1 / C2 halves) ────────────

    /// Helper mirroring `tyc-db::build_external_shapes` for the common
    /// `from producer import <names>` form: extract the producer module's
    /// shapes, re-key class shapes / type-params / variance / HKT under the
    /// (here identical) local import names, and stash the full `by_module`
    /// registry. Returns the parsed+resolved consumer plus its
    /// `ExternalShapes`.
    fn cross_module_external(
        producer_src: &str,
        imported: &[&str],
    ) -> (ModuleShapes, ExternalShapes) {
        let producer_prep = preprocess(producer_src);
        let producer_module = tyc_syntax::parse_module(&producer_prep.python_source)
            .unwrap()
            .into_syntax();
        let producer_shapes = extract_module_shapes(&producer_module);

        let mut external = ExternalShapes::default();
        for name in imported {
            if let Some(shape) = producer_shapes.class_shapes.get(*name) {
                external
                    .class_shapes
                    .insert((*name).to_owned(), shape.clone());
            }
            if let Some(tps) = producer_shapes.class_type_params.get(*name) {
                external
                    .class_type_params
                    .insert((*name).to_owned(), tps.clone());
            }
            if let Some(v) = producer_shapes.class_param_variance.get(*name) {
                external
                    .class_param_variance
                    .insert((*name).to_owned(), v.clone());
            }
        }
        // HKT names are identity tokens, not re-keyed per class — seed the
        // producer's full set, exactly as `build_external_shapes` does.
        for h in &producer_shapes.hkt_param_names {
            external.hkt_param_names.insert(h.clone());
        }
        let mut by_module: HashMap<String, ModuleShapes> = HashMap::new();
        by_module.insert("producer".to_owned(), producer_shapes.clone());
        external.by_module = std::sync::Arc::new(by_module);
        (producer_shapes, external)
    }

    fn check_consumer(consumer_src: &str, external: &ExternalShapes) -> Diagnostics {
        let consumer_prep = preprocess(consumer_src);
        let consumer_module = tyc_syntax::parse_module(&consumer_prep.python_source)
            .unwrap()
            .into_syntax();
        let (resolved, _) = resolve_module(
            "<consumer>".to_owned(),
            &consumer_prep.python_source,
            &consumer_module,
        );
        check_module_with_imports(
            "<consumer>",
            &consumer_prep.python_source,
            &resolved,
            &consumer_module,
            &consumer_prep.unsafe_lines,
            &consumer_prep.frozen_class_lines,
            &consumer_prep.impl_distributed_lines,
            Some(external),
        )
    }

    #[test]
    fn extract_module_shapes_publishes_variance_and_hkt() {
        // The surface-extraction pass must now carry inferred variance
        // (C2) and the HKT constructor-variable set (C1) so the consumer
        // can consult them for imported generics.
        let shapes = extract_module_shapes(
            &tyc_syntax::parse_module(
                &preprocess(
                    "\
class Producer[T]:
    def get(self) -> T:
        ...
class Functor[F]:
    def fmap(self, fa: F[int]) -> F[str]:
        ...
",
                )
                .python_source,
            )
            .unwrap()
            .into_syntax(),
        );
        assert_eq!(
            shapes.class_param_variance.get("Producer"),
            Some(&vec![Variance::Covariant]),
            "Producer[T] (output-only) must publish covariant variance"
        );
        assert!(
            shapes.hkt_param_names.contains("F"),
            "Functor[F[_]]'s constructor variable F must be published as HKT; got {:?}",
            shapes.hkt_param_names
        );
    }

    #[test]
    fn cross_module_covariant_generic_accepts_upcast() {
        // THE C2 GAP CLOSED: a covariant `Producer` imported from another
        // module must widen `Producer[Dog] -> Producer[Animal]` exactly as
        // an in-module `Producer` does.
        let (_p, external) = cross_module_external(
            "\
class Producer[T]:
    def get(self) -> T:
        ...
",
            &["Producer"],
        );
        let consumer_src = "\
class Animal:
    name: str
class Dog(Animal):
    name: str
def use_animals(p: Producer[Animal]) -> None:
    ...
def main(dogs: Producer[Dog]) -> None:
    use_animals(dogs)
";
        let d = check_consumer(consumer_src, &external);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "imported covariant Producer[Dog] -> Producer[Animal] must be accepted; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn cross_module_invariant_generic_rejects_upcast() {
        // SOUNDNESS FLOOR: an imported INVARIANT generic (`Box[T]` with a
        // settable field) must still reject the upcast — variance flows,
        // but it carries the *invariant* verdict too.
        let (_p, external) = cross_module_external(
            "\
class Box[T]:
    value: T
",
            &["Box"],
        );
        let consumer_src = "\
class Animal:
    name: str
class Dog(Animal):
    name: str
def use_animal_box(b: Box[Animal]) -> None:
    ...
def main(dog_box: Box[Dog]) -> None:
    use_animal_box(dog_box)
";
        let d = check_consumer(consumer_src, &external);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "imported invariant Box[Dog] -> Box[Animal] must still be rejected; got {:?}",
            d.errors()
        );
    }

