    // ── H5: scope-blind class unification guard ─────────────────────────
    // RELEASE_READINESS_REVIEW.md H5 — a bare name that refers to a class
    // *declared in the module being checked* must not tail-unify with a
    // same-named class another module provably declares; every uncertain
    // provenance keeps the permissive v0.15.0 unification.

    #[test]
    fn h5_local_class_rejected_against_same_named_foreign_class() {
        // A locally-declared `class Response` is a fresh class — it can
        // never be `producer.Response`, whose declaration (with a
        // different shape) is resolved through the exact module key.
        let external = cross_module_qualified_external(
            "\
class Response:
    text: str
",
        );
        let consumer_src = "\
import producer
class Response:
    status: int
def take(r: producer.Response) -> None:
    ...
def main() -> None:
    let mine: Response = Response(status=3)
    take(mine)
";
        let d = check_consumer(consumer_src, &external);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "local `Response` into a `producer.Response` slot must be rejected (H5); got {:?}",
            d.errors()
        );
    }

    #[test]
    fn h5_qualified_foreign_value_rejected_against_local_class_slot() {
        // The reverse direction: a `producer.Response`-typed value must
        // not satisfy a slot annotated with the local `Response` class.
        let external = cross_module_qualified_external(
            "\
class Response:
    text: str

def fetch() -> Response:
    return Response(text=\"x\")
",
        );
        let consumer_src = "\
import producer
class Response:
    status: int
def take_local(r: Response) -> None:
    ...
def main(remote: producer.Response) -> None:
    take_local(remote)
";
        let d = check_consumer(consumer_src, &external);
        assert!(
            d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "`producer.Response` into a local `Response` slot must be rejected (H5); got {:?}",
            d.errors()
        );
    }

    #[test]
    fn h5_equivalent_shape_reexport_still_unifies() {
        // A facade re-export carries a *copy* of the declaring module's
        // shape. When the local and foreign shapes are equivalent, the
        // names are treated as the same class and unification proceeds —
        // this is the branch that keeps `pub *` facades working.
        let external = cross_module_qualified_external(
            "\
class Node:
    label: str
",
        );
        let consumer_src = "\
import producer
class Node:
    label: str
def take(n: producer.Node) -> None:
    ...
def main() -> None:
    let mine: Node = Node(label=\"a\")
    take(mine)
";
        let d = check_consumer(consumer_src, &external);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "equivalent shapes must keep unifying (facade re-export); got {:?}",
            d.errors()
        );
    }

    #[test]
    fn h5_local_subclass_of_qualified_base_still_unifies() {
        // Codex review of PR #285: a local class that SUBCLASSES the
        // qualified class is a genuine subtype and must keep unifying —
        // qualified (`Expr::Attribute`) bases are collected as
        // `__typhon_unknown_base__`, so the guard must treat an unknown
        // base as "distinctness not provable".
        let external = cross_module_qualified_external(
            "\
class Response:
    text: str
",
        );
        let consumer_src = "\
import producer
class! Response(producer.Response):
    status: int
def take(r: producer.Response) -> None:
    ...
def main() -> None:
    let mine: Response = Response(status=3)
    take(mine)
";
        let d = check_consumer(consumer_src, &external);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "a local subclass of the qualified class must keep unifying; got {:?}",
            d.errors()
        );
    }

    #[test]
    fn h5_bare_name_of_unknown_origin_keeps_unifying() {
        // A bare class name the consumer does NOT declare (an import of
        // unknown provenance) keeps the permissive v0.15.0 unification —
        // this is the shape of the reverted first fix's false positive.
        let external = cross_module_qualified_external(
            "\
class Response:
    text: str

def fetch() -> Response:
    return Response(text=\"x\")
",
        );
        let consumer_src = "\
import producer
def take(r: producer.Response) -> None:
    ...
def relay(r: Response) -> None:
    take(r)
";
        let d = check_consumer(consumer_src, &external);
        assert!(
            !d.errors()
                .iter()
                .any(|e| matches!(e, TycError::TypeMismatch { .. })),
            "bare name of unknown origin must keep unifying; got {:?}",
            d.errors()
        );
    }

    // ── Higher-Kinded Types (HKT) tests ──────────────────────────────────

    #[test]
    fn hkt_type_constructor_single_underscore() {
        // Test that `F[_]` is recognized as a TypeConstructor when F is a type parameter
        use crate::{type_from_annotation_with_params, Type};
        let src = "F[_]";
        let module = tyc_syntax::parse_module(src).unwrap().into_syntax();
        let expr = match &module.body[0] {
            ruff_python_ast::Stmt::Expr(e) => &e.value,
            _ => panic!("expected Expr"),
        };
        // Pass "F" as a type parameter so it's recognized as HKT
        let ty = type_from_annotation_with_params(expr, &[], &["F".to_string()]);
        match ty {
            Type::TypeConstructor(name, arity) => {
                assert_eq!(name, "F");
                assert_eq!(arity, 1);
            }
            other => panic!("expected TypeConstructor, got {:?}", other),
        }
    }

    #[test]
    fn hkt_type_constructor_multiple_underscores() {
        // Test that `G[_, _]` is recognized as a TypeConstructor with arity 2
        use crate::{type_from_annotation_with_params, Type};
        let src = "G[_, _]";
        let module = tyc_syntax::parse_module(src).unwrap().into_syntax();
        let expr = match &module.body[0] {
            ruff_python_ast::Stmt::Expr(e) => &e.value,
            _ => panic!("expected Expr"),
        };
        // Pass "G" as a type parameter so it's recognized as HKT
        let ty = type_from_annotation_with_params(expr, &[], &["G".to_string()]);
        match ty {
            Type::TypeConstructor(name, arity) => {
                assert_eq!(name, "G");
                assert_eq!(arity, 2);
            }
            other => panic!("expected TypeConstructor, got {:?}", other),
        }
    }

    #[test]
    fn hkt_type_constructor_display() {
        // Test that TypeConstructor displays correctly
        use crate::Type;
        let tc = Type::TypeConstructor("Functor".to_string(), 1);
        assert_eq!(tc.display(), "Functor[_]");

        let tc2 = Type::TypeConstructor("Bifunctor".to_string(), 2);
        assert_eq!(tc2.display(), "Bifunctor[_, _]");
    }

    #[test]
    fn hkt_type_constructor_binding() {
        // Test that TypeConstructor binds correctly in bind_typevars (HKT unification)
        use crate::{compute_bidirectional_bindings, Type};

        // Simulate a function like: def map[F[_], A, B](fa: F[A], f: A -> B) -> F[B]
        // Test that binding works through the public API
        let tc_a = Type::TypeConstructor("F".to_string(), 1);
        let list_int = Type::Generic("list".to_string(), vec![Type::Int]);

        // TypeConstructor should NOT be universally assignable anymore
        // (it was removed from assignable to fix the security issue)
        assert!(!crate::assignable(&tc_a, &list_int));
        assert!(!crate::assignable(&list_int, &tc_a));

        // Test that it works in the binding context through the public API
        // Call as if we had: def f[F[_]](x: F[int]) -> F[str]
        // with argument list[int]
        let formal_params = vec![tc_a.clone()];
        let actual_args = vec![list_int.clone()];
        let return_type = Type::TypeConstructor("F".to_string(), 1);

        let bindings =
            compute_bidirectional_bindings(&formal_params, &actual_args, &return_type, None);

        // After binding, F should be bound to "list"
        assert_eq!(bindings.get("F"), Some(&Type::Class("list".to_string())));
    }

    // ── HKT substitute_typevars head-substitution tests ──────────────────
    //
    // These tests verify the `substitute_typevars` fix for HKT: when a
    // TypeConstructor name (e.g. "F") is bound to a Class via `bind_typevars`
    // (e.g. `F → list` from matching `TypeConstructor("F", 1)` against
    // `Generic("list", [Int])`), the return type `F[B]` (which is
    // `Generic("F", [TypeVar("B")])`) must be rewritten to `list[B]`
    // (and further to `list[int]` if B is also bound).
    //
    // All tests use the public `bind_typevars_and_substitute` API so they
    // don't depend on the visibility of the internal `substitute_typevars`
    // helper.

    #[test]
    fn hkt_substitute_bound_constructor_head_in_return_generic() {
        // `def f[F[_]](fa: F[int]) -> F[str]` with actual `list[int]`.
        // Formal TypeConstructor("F",1) against Generic("list",[Int]) → F→list.
        // Return Generic("F",[Str]) should resolve to Generic("list",[Str]).
        use crate::{bind_typevars_and_substitute, Type};

        let formal_params = vec![Type::TypeConstructor("F".to_string(), 1)];
        let actual_args = vec![Type::Generic("list".to_string(), vec![Type::Int])];
        let return_type = Type::Generic("F".to_string(), vec![Type::Str]);

        let result = bind_typevars_and_substitute(&formal_params, &actual_args, &return_type);
        assert_eq!(
            result,
            Type::Generic("list".to_string(), vec![Type::Str]),
            "return Generic(F,[Str]) must resolve to Generic(list,[Str]) when F→list; got {result:?}"
        );
    }

    #[test]
    fn hkt_substitute_replaces_head_and_arg_typevar() {
        // `def f[F[_]](fa: F[_], a: A) -> F[A]` with actuals `list[int]`, `str`.
        // Two separate formal/actual pairs: TypeConstructor("F",1)→list and
        // TypeVar("A")→Str.  Return Generic("F",[TypeVar("A")]) must become
        // Generic("list",[Str]).
        use crate::{bind_typevars_and_substitute, Type};

        let formal_params = vec![
            Type::TypeConstructor("F".to_string(), 1),
            Type::TypeVar("A".to_string()),
        ];
        let actual_args = vec![
            Type::Generic("list".to_string(), vec![Type::Int]),
            Type::Str,
        ];
        let return_type = Type::Generic("F".to_string(), vec![Type::TypeVar("A".to_string())]);

        let result = bind_typevars_and_substitute(&formal_params, &actual_args, &return_type);
        assert_eq!(
            result,
            Type::Generic("list".to_string(), vec![Type::Str]),
            "return Generic(F,[A]) must become Generic(list,[Str]); got {result:?}"
        );
    }

    #[test]
    fn hkt_bare_type_constructor_in_return_resolves_to_class() {
        // `def f[F[_]](fa: F) -> F` with actual `list[int]`.
        // The return type is a bare TypeConstructor (not applied); it should
        // resolve to Class("list") after substitution.
        use crate::{bind_typevars_and_substitute, Type};

        let formal_params = vec![Type::TypeConstructor("F".to_string(), 1)];
        let actual_args = vec![Type::Generic("list".to_string(), vec![Type::Int])];
        let return_type = Type::TypeConstructor("F".to_string(), 1);

        let result = bind_typevars_and_substitute(&formal_params, &actual_args, &return_type);
        assert_eq!(
            result,
            Type::Class("list".to_string()),
            "bare TypeConstructor return must resolve to Class(list); got {result:?}"
        );
    }

    #[test]
    fn hkt_concrete_generic_head_unchanged_without_binding() {
        // A concrete `list[int]` in the return type must NOT be modified when
        // there are no TypeConstructor bindings — the common case.
        use crate::{bind_typevars_and_substitute, Type};

        let formal_params = vec![Type::TypeVar("T".to_string())];
        let actual_args = vec![Type::Int];
        let return_type = Type::Generic("list".to_string(), vec![Type::Int]);

        let result = bind_typevars_and_substitute(&formal_params, &actual_args, &return_type);
        assert_eq!(
            result,
            Type::Generic("list".to_string(), vec![Type::Int]),
            "concrete Generic head must survive unchanged; got {result:?}"
        );
    }

    #[test]
    fn hkt_non_class_binding_does_not_replace_generic_head() {
        // When the binding for the head name is NOT a Class (e.g. TypeVar → Int),
        // the Generic head must NOT be replaced.  In practice this means a
        // TypeVar "T" bound to Int cannot clobber a Generic head "T".
        use crate::{bind_typevars_and_substitute, Type};

        // Force `T → Int` by matching TypeVar("T") against Int.
        let formal_params = vec![Type::TypeVar("T".to_string())];
        let actual_args = vec![Type::Int];
        // Return type has Generic("T", [Str]) — T is Int not a Class, so head stays.
        let return_type = Type::Generic("T".to_string(), vec![Type::Str]);

        let result = bind_typevars_and_substitute(&formal_params, &actual_args, &return_type);
        // T was bound to Int (not a Class), so the Generic head "T" must survive.
        assert_eq!(
            result,
            Type::Generic("T".to_string(), vec![Type::Str]),
            "non-Class binding must not replace Generic head; got {result:?}"
        );
    }

    // ── HKT application: F[A] formal unifying against a concrete ctor ─────
    //
    // These exercise the new `bind_typevars_and_substitute_hkt` path, where
    // the formal is `Generic("F", [TypeVar("A")])` (how `fa: F[A]` actually
    // parses) — distinct from the older bare-`TypeConstructor("F", 1)` form.

    #[test]
    fn hkt_applied_ctor_var_binds_head_and_arg() {
        // Formal `F[A]` against actual `list[int]` with F a constructor var:
        // binds F → list and A → int, and the return `F[B]` (with B bound to
        // str elsewhere) substitutes to `list[str]`.
        use crate::{bind_typevars_and_substitute_hkt, Type};
        use std::collections::HashSet;

        let ctor_vars: HashSet<String> = ["F".to_string()].into_iter().collect();
        // def fmap[A, B](fa: F[A], b: B) -> F[B]
        let formal_params = vec![
            Type::Generic("F".to_string(), vec![Type::TypeVar("A".to_string())]),
            Type::TypeVar("B".to_string()),
        ];
        let actual_args = vec![
            Type::Generic("list".to_string(), vec![Type::Int]),
            Type::Str,
        ];
        let return_type = Type::Generic("F".to_string(), vec![Type::TypeVar("B".to_string())]);

        let (result, errors) = bind_typevars_and_substitute_hkt(
            &formal_params,
            &actual_args,
            &return_type,
            None,
            &ctor_vars,
        );
        assert!(errors.is_empty(), "no kind errors expected; got {errors:?}");
        assert_eq!(
            result,
            Type::Generic("list".to_string(), vec![Type::Str]),
            "F[B] must resolve to list[str] when F→list and B→str; got {result:?}"
        );
    }

    #[test]
    fn hkt_applied_ctor_var_arity_mismatch_is_reported() {
        // Formal `F[A, B]` (a 2-ary application) against `list[int]` (1-ary)
        // is ill-kinded.
        use crate::{bind_typevars_and_substitute_hkt, KindError, Type};
        use std::collections::HashSet;

        let ctor_vars: HashSet<String> = ["F".to_string()].into_iter().collect();
        let formal_params = vec![Type::Generic(
            "F".to_string(),
            vec![
                Type::TypeVar("A".to_string()),
                Type::TypeVar("B".to_string()),
            ],
        )];
        let actual_args = vec![Type::Generic("list".to_string(), vec![Type::Int])];
        let return_type = Type::None;

        let (_result, errors) = bind_typevars_and_substitute_hkt(
            &formal_params,
            &actual_args,
            &return_type,
            None,
            &ctor_vars,
        );
        assert!(
            errors
                .iter()
                .any(|e| matches!(e, KindError::Arity { ctor, expected, actual }
                    if ctor == "F" && *expected == 2 && *actual == 1)),
            "expected an Arity kind error for F; got {errors:?}"
        );
    }

    #[test]
    fn hkt_applied_ctor_var_conflicting_constructors_is_reported() {
        // `F[A]` matched against `list[int]` then `F[A]` against `set[int]`
        // binds F to two different constructors — a conflict.
        use crate::{bind_typevars_and_substitute_hkt, KindError, Type};
        use std::collections::HashSet;

        let ctor_vars: HashSet<String> = ["F".to_string()].into_iter().collect();
        let formal_params = vec![
            Type::Generic("F".to_string(), vec![Type::TypeVar("A".to_string())]),
            Type::Generic("F".to_string(), vec![Type::TypeVar("A".to_string())]),
        ];
        let actual_args = vec![
            Type::Generic("list".to_string(), vec![Type::Int]),
            Type::Generic("set".to_string(), vec![Type::Int]),
        ];
        let return_type = Type::None;

        let (_result, errors) = bind_typevars_and_substitute_hkt(
            &formal_params,
            &actual_args,
            &return_type,
            None,
            &ctor_vars,
        );
        assert!(
            errors
                .iter()
                .any(|e| matches!(e, KindError::Conflict { ctor, .. } if ctor == "F")),
            "expected a Conflict kind error for F; got {errors:?}"
        );
    }

    #[test]
    fn hkt_empty_ctor_vars_matches_legacy_behaviour() {
        // With an empty constructor set, the HKT entry point must produce
        // exactly the same result as the legacy bidirectional substitution —
        // so a `Generic("F", ...)` mismatch binds nothing and the return
        // type is unchanged (today's conservative behaviour).
        use crate::{bind_typevars_and_substitute_hkt, Type};
        use std::collections::HashSet;

        let ctor_vars: HashSet<String> = HashSet::new();
        let formal_params = vec![Type::Generic(
            "F".to_string(),
            vec![Type::TypeVar("A".to_string())],
        )];
        let actual_args = vec![Type::Generic("list".to_string(), vec![Type::Int])];
        let return_type = Type::Generic("F".to_string(), vec![Type::TypeVar("A".to_string())]);

        let (result, errors) = bind_typevars_and_substitute_hkt(
            &formal_params,
            &actual_args,
            &return_type,
            None,
            &ctor_vars,
        );
        assert!(errors.is_empty());
        assert_eq!(
            result,
            Type::Generic("F".to_string(), vec![Type::TypeVar("A".to_string())]),
            "empty ctor set must leave F[A] unbound; got {result:?}"
        );
    }

    #[test]
    fn hkt_backward_ctor_var_arity_mismatch_is_reported() {
        // Backward (return-type-driven) inference: a no-arg signature whose
        // return is `F[A]` (a genuine constructor var) used where the
        // EXPECTED type is `dict[str, int]`. Binding `F[A]` (1 arg) against
        // `dict[str, int]` (2 args) is an arity mismatch. The forward pass
        // binds nothing (no actual args mention F), so the error can only be
        // discovered backward — and must surface, not be silently dropped.
        use crate::{bind_typevars_and_substitute_hkt, KindError, Type};
        use std::collections::HashSet;

        let ctor_vars: HashSet<String> = ["F".to_string()].into_iter().collect();
        let formal_params: Vec<Type> = vec![];
        let actual_args: Vec<Type> = vec![];
        let return_type = Type::Generic("F".to_string(), vec![Type::TypeVar("A".to_string())]);
        let expected = Type::Generic("dict".to_string(), vec![Type::Str, Type::Int]);

        let (_result, errors) = bind_typevars_and_substitute_hkt(
            &formal_params,
            &actual_args,
            &return_type,
            Some(&expected),
            &ctor_vars,
        );
        assert!(
            errors
                .iter()
                .any(|e| matches!(e, KindError::Arity { ctor, expected, actual }
                    if ctor == "F" && *expected == 1 && *actual == 2)),
            "backward F[A] vs dict[str, int] must report an Arity kind error; got {errors:?}"
        );
    }

    #[test]
    fn hkt_backward_ctor_var_matching_arity_binds_clean() {
        // The legitimate backward case: return `F[A]` used where `list[int]`
        // is expected → `F=list, A=int`, no error, return resolves to
        // `list[int]`. This must keep succeeding silently after the fix.
        use crate::{bind_typevars_and_substitute_hkt, Type};
        use std::collections::HashSet;

        let ctor_vars: HashSet<String> = ["F".to_string()].into_iter().collect();
        let formal_params: Vec<Type> = vec![];
        let actual_args: Vec<Type> = vec![];
        let return_type = Type::Generic("F".to_string(), vec![Type::TypeVar("A".to_string())]);
        let expected = Type::Generic("list".to_string(), vec![Type::Int]);

        let (result, errors) = bind_typevars_and_substitute_hkt(
            &formal_params,
            &actual_args,
            &return_type,
            Some(&expected),
            &ctor_vars,
        );
        assert!(
            errors.is_empty(),
            "matching-arity backward HKT binding must not error; got {errors:?}"
        );
        assert_eq!(
            result,
            Type::Generic("list".to_string(), vec![Type::Int]),
            "F[A] vs list[int] must resolve F→list, A→int; got {result:?}"
        );
    }

    // ── HKT end-to-end: Functor-style map over concrete constructors ─────

    #[test]
    fn hkt_functor_map_over_list_typechecks() {
        // The canonical scaffold: `class Functor[F[_]]` with a `map` method
        // shaped `F[A] -> F[B]`. Calling it with a `list[int]` argument must
        // type-check clean (F binds to list, the call is well-kinded).
        let src = "\
class Functor[F[_]]:
    def fmap[A, B](self, fa: F[A], f: B) -> F[B]:
        return fa

def main() -> None:
    let xs: list[int] = [1, 2, 3]
    let _ys = Functor().fmap(xs, \"tag\")
";
        let d = check(src);
        assert!(
            d.errors().is_empty(),
            "Functor.fmap over list[int] must check clean; got {:?}",
            d.errors()
        );
    }

